window.CSS_DATA = (window.CSS_DATA || []).concat([{"name":"bottom","js":"bottom","zh":"底部偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"设置定位元素下边缘相对包含块底部的偏移","description":"对相对、绝对、固定定位元素指定下边缘相对包含块底部的距离，sticky 定位中也用它设定粘附阈值。auto 表示由浏览器按定位规则计算，不参与偏移。百分比以包含块高度为基准；当 top 与 bottom 同时指定且 height 为 auto 时，元素会被拉伸而不是只取其中一个值。","aliases":["底部偏移","下偏移","bottom offset","bottom"],"keywords":["定位","偏移","布局","上下"],"values":[{"v":"auto","d":"初始值，由浏览器根据定位规则自动计算偏移。"},{"v":"<length>","d":"长度值，如 0、12px、1.5rem，可为负值。"},{"v":"<percentage>","d":"相对包含块高度的百分比，如 50%。"},{"v":"<anchor()>","d":"锚点定位函数，让元素下边缘对齐指定锚点，属较新特性。"}],"example":".demo {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n}","notes":["top 与 bottom 同时设置且 height 为 auto 时元素会被拉伸。","静态定位（position: static）下该属性不生效。"],"syntax":"auto | <length-percentage> | <anchor()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块高度","appliesTo":"定位元素","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Anchor Positioning","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/bottom","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"bottom","order":217},{"name":"clear","js":"clear","zh":"清除浮动","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"指定元素的哪一侧不允许紧邻浮动元素","description":"用于块级元素，使元素某侧不与前面的浮动元素相邻，从而被挤到浮动元素下方，是清除浮动布局影响的核心属性。left、right、both 分别清除左、右、两侧浮动；inline-start 与 inline-end 则随书写方向对应逻辑侧。它只对块级盒子生效，在弹性或网格容器中浮动本身不生效。","aliases":["清除浮动","清浮动","clear float","clear"],"keywords":["浮动","清除","换行","布局"],"values":[{"v":"none","d":"初始值，允许两侧存在浮动元素。"},{"v":"left","d":"左侧不允许有浮动元素，元素下移到左浮动元素下方。"},{"v":"right","d":"右侧不允许有浮动元素。"},{"v":"both","d":"两侧都不允许浮动元素，最常用。"},{"v":"inline-start","d":"逻辑值，行内起始侧不允许浮动，随书写方向翻转。"},{"v":"inline-end","d":"逻辑值，行内结束侧不允许浮动。"}],"example":".demo {\n  clear: both;\n}","notes":["现代布局优先用 flex/grid，clear 主要用于维护旧代码。","clear 只对块级盒子有作用，不影响行内元素。"],"syntax":"none | left | right | both | inline-start | inline-end","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级元素","computed":"按指定值","specGroups":["CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/clear","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"clear","order":237},{"name":"contain","js":"contain","zh":"包含性隔离","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"声明元素子树与外部相互隔离以优化渲染","description":"告诉浏览器元素的布局、样式和绘制与外部互不影响，从而跳过本不必要的重排重绘，常用于长列表与复杂组件的性能优化。strict 等价于 size layout paint style，content 等价于 layout paint style。注意 size 会让元素尺寸不再由内容决定，必须显式给出宽高，否则内容会溢出且盒子塌缩。","aliases":["布局隔离","渲染隔离","contain","CSS contain"],"keywords":["性能","隔离","渲染","优化"],"values":[{"v":"none","d":"初始值，不做任何隔离。"},{"v":"strict","d":"等价于 size layout paint style，隔离最彻底。"},{"v":"content","d":"等价于 layout paint style，保留元素自身尺寸由内容决定。"},{"v":"size","d":"尺寸包含，元素尺寸不再依赖内容，需显式设置宽高。"},{"v":"inline-size","d":"只隔离行内尺寸，元素宽度不再由内容决定。"},{"v":"layout","d":"布局包含，外部改动不会影响内部布局。"},{"v":"style","d":"样式包含，限定计数器与引号等可继承样式的影响范围。"},{"v":"paint","d":"绘制包含，裁剪溢出内容并创建新的包含块与层叠上下文。"}],"example":".demo {\n  contain: content;\n  width: 320px;\n}","notes":["contain: size 或 strict 后元素高度可能塌缩，务必显式指定尺寸。","contain 只影响渲染优化，不会改变视觉结果。"],"syntax":"none | strict | content | [ [ size || inline-size ] || layout || style || paint ]","initial":"none","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Containment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain","browser":{"chrome":"52","firefox":"69","safari":"15.4","edge":"79"},"tier":"core","tags":[],"id":"contain","order":256},{"name":"container","js":"container","zh":"容器简写","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"同时设置容器名称与容器类型","description":"container-name 与 container-type 的简写，标准写法是「名称 / 类型」，如 container: card / inline-size。容器查询的前提就是它：只有声明了容器类型的元素才能作为 @container 的查询对象。只写一个值时会被识别为容器类型，名称不能使用 none 这类保留关键字。","aliases":["容器查询简写","container shorthand","container"],"keywords":["容器查询","简写","响应式","组件"],"values":[{"v":"<name> / <type>","d":"名称与类型用斜杠分隔，如 card / inline-size。"},{"v":"<type>","d":"只写类型时省略名称，成为匿名容器，如 container: inline-size。"},{"v":"none","d":"等价于 container-name: none; container-type: normal，不建立查询容器。"}],"example":".demo {\n  container: card / inline-size;\n}","notes":["等价于 container-name: card; container-type: inline-size;。","写成单值时会按容器类型解析，容易与只设名称混淆。"],"syntax":"<'container-name'> [ / <'container-type'> ]?","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"所有元素","computed":"由各长写属性决定","specGroups":["CSS Conditional Rules"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/container","browser":{"chrome":"105","firefox":"110","safari":"16","edge":"105"},"tier":"core","tags":["可动画","简写"],"id":"container","order":262},{"name":"container-name","js":"containerName","zh":"容器名称","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"为元素命名供容器查询按名匹配","description":"给元素一个可在 @container 规则中引用的自定义名称，多个名称用空格分隔，同一容器可被多条不同查询匹配。必须配合 container-type 才能成为查询容器，例如 container-type: inline-size 后即可写 @container card (min-width: 400px)。页面中有多个容器时，命名比匿名查询更可控。","aliases":["容器名","container-name","container name"],"keywords":["容器查询","命名","响应式"],"values":[{"v":"none","d":"初始值，不设置容器名称，只能被匿名查询匹配。"},{"v":"<custom-ident>","d":"自定义标识符，如 card、sidebar，区分大小写。"},{"v":"<custom-ident>+","d":"多个名称以空格分隔，可同时响应多条具名查询。"}],"example":".demo {\n  container-name: card;\n  container-type: inline-size;\n}","notes":["只设置名称而不设置 container-type 时元素不会成为查询容器。","名称不能使用 none 等关键字。"],"syntax":"none | <custom-ident>+","initial":"none","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"所有元素","computed":"none 或有序标识符列表","specGroups":["CSS Conditional Rules"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/container-name","browser":{"chrome":"105","firefox":"110","safari":"16","edge":"105"},"tier":"core","tags":[],"id":"container-name","order":263},{"name":"container-type","js":"containerType","zh":"容器类型","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"声明元素可作为容器查询的查询维度","description":"决定元素能响应哪一类容器查询。inline-size 让元素按行内尺寸被查询，是最常用的取值，同时建立尺寸包含；size 同时响应宽高，但会让元素尺寸与内容解耦，需要谨慎；normal 表示不建立查询容器。设置后元素会成为新的包含块，内部绝对定位元素与百分比尺寸的参照会随之改变，排查定位问题时需要留意。","aliases":["容器类型","container-type","container type"],"keywords":["容器查询","尺寸","响应式","包含"],"values":[{"v":"normal","d":"初始值，元素不是查询容器，行为与普通元素一致。"},{"v":"inline-size","d":"按行内方向尺寸响应查询，横排页面即响应宽度，最常用。"},{"v":"size","d":"同时响应宽高两个维度，元素尺寸不再由内容决定，需指定尺寸。"},{"v":"scroll-state","d":"建立滚动状态查询容器，用于查询滚动位置等状态，较新特性。"}],"example":".demo {\n  container-type: inline-size;\n  width: 100%;\n}","notes":["建立容器后元素产生尺寸包含，内部百分比尺寸的参照随之改变。","inline-size 只影响行内轴，纵排书写模式下会响应高度。"],"syntax":"normal | [ [ size | inline-size ] || scroll-state ]","initial":"normal","inherited":"否","animation":"颜色插值","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Conditional Rules"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/container-type","browser":{"chrome":"105","firefox":"110","safari":"16","edge":"105"},"tier":"core","tags":["可动画"],"id":"container-type","order":264},{"name":"content-visibility","js":"contentVisibility","zh":"内容可见性","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"跳过屏幕外元素的内容渲染以提升性能","description":"auto 让浏览器跳过视口外元素的内容渲染，滚动进入视口附近时才真正渲染，能显著改善超长页面的首屏与滚动性能。hidden 连布局都跳过，元素尺寸为 0，但内容仍可通过 find-in-page 等机制被找到。使用时通常配合 contain-intrinsic-size 给出占位尺寸，否则滚动条长度会不断跳动。","aliases":["内容可见性","content-visibility","延迟渲染"],"keywords":["性能","渲染","懒加载","长列表"],"values":[{"v":"visible","d":"初始值，正常渲染内容。"},{"v":"auto","d":"视口外跳过内容渲染，进入视口时再渲染，保留元素占位。"},{"v":"hidden","d":"完全跳过内容渲染与布局，元素尺寸为 0，仍保留在可访问性树外。"}],"example":".demo {\n  content-visibility: auto;\n  contain-intrinsic-size: 600px;\n}","notes":["务必配合 contain-intrinsic-size 指定占位高度，减少滚动条抖动。","hidden 的元素内容不会被辅助技术读取，不应用于需要无障碍访问的内容。"],"syntax":"visible | auto | hidden","initial":"visible","inherited":"否","animation":"离散过渡（可配合 transition-behavior: allow-discrete）","percentages":"不适用","appliesTo":"可应用尺寸包含的元素","computed":"按指定值","specGroups":["CSS Containment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/content-visibility","browser":{"chrome":"85","firefox":"125","safari":"18","edge":"85"},"tier":"core","tags":["可动画"],"id":"content-visibility","order":266},{"name":"display","js":"display","zh":"显示类型","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"设置元素的外部与内部显示类型","description":"决定元素如何参与外层布局、子元素又如何排布，是最基础也最常被覆盖的属性。新语法可拆成外部类型（block、inline）与内部类型（flow、flow-root、flex、grid、table），因此 flex 等价于 block flex；none 使元素不生成盒子、整棵子树不参与布局与渲染，与 visibility: hidden 保留占位的行为不同。","aliases":["显示方式","显示类型","display","显示属性"],"keywords":["布局","显示","块级","行内","弹性"],"values":[{"v":"block","d":"块级盒子，独占一行，可设宽高与外边距。"},{"v":"inline","d":"行内盒子，随文字流排列，宽高由内容决定。"},{"v":"inline-block","d":"行内排列但内部按块级格式化，可设宽高与垂直间距。"},{"v":"flex","d":"块级弹性容器，子项沿主轴排布。"},{"v":"inline-flex","d":"行内级弹性容器，容器本身随文字流排列。"},{"v":"grid","d":"块级网格容器，用行列定义二维布局。"},{"v":"none","d":"不生成盒子，元素及其子树完全不渲染、不占位。"},{"v":"contents","d":"元素盒子消失，子元素按父级上下文继续参与布局。"}],"example":".demo {\n  display: flex;\n  gap: 1rem;\n}","notes":["display: none 的元素不会渲染也不占位，visibility: hidden 仍占位。","display 变化属于离散动画，无法在不同布局类型间平滑过渡。"],"syntax":"[ <display-outside> || <display-inside> ] | <display-listitem> | <display-internal> | <display-box> | <display-legacy>","initial":"inline","inherited":"否","animation":"离散过渡（可配合 transition-behavior: allow-discrete）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值（定位、浮动与根元素可能不同）","specGroups":["CSS Display"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/display","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"display","order":292},{"name":"float","js":"float","zh":"浮动","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"让元素靠向容器一侧并使文字环绕","description":"使元素脱离正常流并靠向所在块的左侧或右侧，后续行内内容环绕它排列，是早期页面布局的主要手段。left、right 为物理方向，inline-start、inline-end 随书写方向变化。浮动元素会被块级化，其高度不参与父元素高度计算，因此常导致父容器高度塌陷，需要用 clear 或建立块级格式化上下文来处理。","aliases":["浮动","float","文字环绕","左浮动"],"keywords":["浮动","环绕","清除浮动","布局"],"values":[{"v":"none","d":"初始值，元素不浮动。"},{"v":"left","d":"向左浮动，元素靠容器左侧，内容环绕右侧。"},{"v":"right","d":"向右浮动，元素靠容器右侧，内容环绕左侧。"},{"v":"inline-start","d":"逻辑值，向行内起始侧浮动，随书写方向翻转。"},{"v":"inline-end","d":"逻辑值，向行内结束侧浮动。"}],"example":".demo {\n  float: left;\n  width: 120px;\n  margin-right: 1rem;\n}","notes":["浮动元素不撑开父元素高度，会造成高度塌陷。","在弹性或网格容器中 float 不生效。"],"syntax":"left | right | none | inline-start | inline-end","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素（display: none 时无效）","computed":"按指定值","specGroups":["CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/float","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"float","order":309},{"name":"inset","js":"inset","zh":"内嵌偏移简写","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"一次性设置四边偏移距离","description":"top、right、bottom、left 的简写，取值规则与 margin 相同：1 个值四边相同，2 个值依次为上下、左右，3 个值为上、左右、下，4 个值按上右下左顺时针。只对定位元素生效，inset: 0 是让遮罩层或弹层贴合包含块四边的常用写法。它属于物理方向简写，对应的逻辑简写是 inset-block 与 inset-inline。","aliases":["内嵌简写","inset shorthand","inset","四边偏移"],"keywords":["定位","简写","偏移","四边"],"values":[{"v":"<length>{1,4}","d":"1 至 4 个长度值，按上右下左规则分配。"},{"v":"<percentage>{1,4}","d":"百分比相对包含块尺寸，水平方向按宽度、垂直方向按高度。"},{"v":"auto","d":"四边均为 auto，由浏览器按定位规则计算。"}],"example":".demo {\n  position: absolute;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.4);\n}","notes":["inset: 0 常用于遮罩层、弹层铺满包含块。","逻辑方向简写为 inset-block 与 inset-inline。"],"syntax":"<'top'>{1,4}","initial":"由各长写属性决定","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑高或宽","appliesTo":"定位元素","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset","browser":{"chrome":"87","firefox":"66","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"inset","order":373},{"name":"inset-block","js":"insetBlock","zh":"块向内嵌简写","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"同时设置块向起始与结束侧偏移","description":"inset-block-start 与 inset-block-end 的简写，按书写模式映射到物理的上下边（横排）或左右边（竖排）。1 个值表示两端相同，2 个值依次为起始、结束。在需要同时支持横排与竖排的多语言页面中，用它替代 top/bottom 组合能自动适配方向，避免为不同书写方向维护两套偏移。","aliases":["块向偏移简写","inset-block","inset block"],"keywords":["定位","逻辑属性","简写","书写模式"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个长度值，对应块向起始与结束。"},{"v":"<percentage>{1,2}","d":"百分比相对包含块块向尺寸。"},{"v":"auto","d":"两端均为 auto，由定位规则计算。"}],"example":".demo {\n  position: absolute;\n  inset-block: 0;\n}","notes":["横排书写模式下等价于 top: 0; bottom: 0。","属于 inset 简写族，可与 inset-inline 组合成完整四边偏移。"],"syntax":"<'top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑高度","appliesTo":"定位元素","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-block","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"inset-block","order":374},{"name":"inset-block-end","js":"insetBlockEnd","zh":"块向结束偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴结束侧的偏移","description":"逻辑属性，作用于块轴结束侧。横排从上到下书写时等价于 bottom，竖排书写时则对应左或右边，随 writing-mode 自动切换。值语义与 top 完全一致，支持 auto、长度与百分比（百分比基于包含块块向尺寸）。它属于 inset 简写族，通常与 inset-block-start 成对使用。","aliases":["块向结束偏移","inset-block-end","块尾偏移"],"keywords":["定位","逻辑属性","偏移","书写模式"],"values":[{"v":"auto","d":"初始值，不参与偏移计算。"},{"v":"<length>","d":"长度值，如 0、16px，可为负值。"},{"v":"<percentage>","d":"相对包含块块向尺寸的百分比。"}],"example":".demo {\n  position: absolute;\n  inset-block-end: 8px;\n}","notes":["横排书写模式下完全等同 bottom。","竖排（writing-mode: vertical-rl）时对应左侧。"],"syntax":"<'top'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑高度","appliesTo":"定位元素","computed":"与盒偏移相同","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-block-end","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性"],"id":"inset-block-end","order":375},{"name":"inset-block-start","js":"insetBlockStart","zh":"块向起始偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴起始侧的偏移","description":"逻辑属性，作用于块轴起始侧。横排书写时等价于 top，竖排时对应右或左边。取值与 top 相同，支持 auto、长度与百分比。它与 inset-block-end 共同构成 inset-block 简写，适合需要同时适配横竖排版或 RTL 的组件，例如吸顶导航用 inset-block-start: 0。","aliases":["块向起始偏移","inset-block-start","块首偏移"],"keywords":["定位","逻辑属性","吸顶","书写模式"],"values":[{"v":"auto","d":"初始值，不参与偏移计算。"},{"v":"<length>","d":"长度值，如 0、24px。"},{"v":"<percentage>","d":"相对包含块块向尺寸的百分比。"}],"example":".demo {\n  position: sticky;\n  inset-block-start: 0;\n}","notes":["sticky 定位用它可以实现随书写方向自适应的吸顶。","横排书写模式下等价于 top。"],"syntax":"<'top'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑高度","appliesTo":"定位元素","computed":"与盒偏移相同","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-block-start","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性"],"id":"inset-block-start","order":376},{"name":"inset-inline","js":"insetInline","zh":"行向内嵌简写","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"同时设置行向起始与结束侧偏移","description":"inset-inline-start 与 inset-inline-end 的简写。横排 LTR 下对应 left 与 right，RTL 下方向自动翻转，因此在多语言页面中比直接写 left/right 更稳妥。1 个值表示两端相同，2 个值依次为起始、结束。常与 inset-block 搭配，用两条声明写完全部四边偏移。","aliases":["行向偏移简写","inset-inline","inset inline"],"keywords":["定位","逻辑属性","简写","国际化"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个长度值，对应行向起始与结束。"},{"v":"<percentage>{1,2}","d":"百分比相对包含块行向尺寸。"},{"v":"auto","d":"两端均为 auto。"}],"example":".demo {\n  position: absolute;\n  inset-inline: 0;\n}","notes":["横排 LTR 下等价于 left: 0; right: 0。","RTL 页面中起始侧自动变为右侧，无需额外覆盖。"],"syntax":"<'top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑宽度","appliesTo":"定位元素","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-inline","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"inset-inline","order":377},{"name":"inset-inline-end","js":"insetInlineEnd","zh":"行向结束偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴结束侧的偏移","description":"逻辑属性，作用于行轴结束侧。横排 LTR 时等价于 right，RTL 时等价于 left，方向随 direction 与 writing-mode 自动翻转。支持 auto、长度与百分比，百分比相对包含块行向尺寸。属于 inset 简写族，是国际化布局中替代 right 的首选写法，能让图标或角标在镜像语言下自动换边。","aliases":["行向结束偏移","inset-inline-end","行尾偏移"],"keywords":["定位","逻辑属性","国际化","偏移"],"values":[{"v":"auto","d":"初始值，由浏览器按定位规则计算。"},{"v":"<length>","d":"长度值，如 0、12px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  position: absolute;\n  inset-inline-end: 1rem;\n}","notes":["LTR 下等同 right，RTL 下会自动变成左侧。","与 inset-inline-start 一起构成 inset-inline 简写。"],"syntax":"<'top'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑宽度","appliesTo":"定位元素","computed":"与盒偏移相同","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-inline-end","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性"],"id":"inset-inline-end","order":378},{"name":"inset-inline-start","js":"insetInlineStart","zh":"行向起始偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴起始侧的偏移","description":"逻辑属性，作用于行轴起始侧。横排 LTR 时等价于 left，RTL 时等价于 right，跟随书写方向自动镜像。取值与 left 一致，支持 auto、长度与百分比。相对定位中常用于微调水平位置，在图标与文字需要随语言镜像的界面里比 left 更可靠。","aliases":["行向起始偏移","inset-inline-start","行首偏移"],"keywords":["定位","逻辑属性","国际化","偏移"],"values":[{"v":"auto","d":"初始值，由浏览器计算。"},{"v":"<length>","d":"长度值，如 0、4px，可为负值。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  position: relative;\n  inset-inline-start: 4px;\n}","notes":["LTR 下等同 left；切换到 RTL 后自动改为右侧偏移。","与 inset-block-start 组合可替代 top + left。"],"syntax":"<'top'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块逻辑宽度","appliesTo":"定位元素","computed":"与盒偏移相同","specGroups":["CSS Logical Properties and Values","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inset-inline-start","browser":{"chrome":"87","firefox":"63","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性"],"id":"inset-inline-start","order":379},{"name":"left","js":"left","zh":"左侧偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"设置定位元素左边缘相对包含块的偏移","description":"对定位元素指定左边缘相对包含块左侧的距离，百分比相对包含块宽度。absolute 与 fixed 下与 top 等组合决定最终位置；relative 下作为相对自身原位的视觉位移，不改变其他元素布局。left 与 right 同时指定且 width 为 auto 时会拉伸宽度而非取其中一个值。","aliases":["左侧偏移","左偏移","left offset","left"],"keywords":["定位","偏移","左右","布局"],"values":[{"v":"auto","d":"初始值，由浏览器按定位规则计算。"},{"v":"<length>","d":"长度值，如 0、24px、-8px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"<anchor()>","d":"锚点定位函数，让元素左边缘对齐锚点，属较新特性。"}],"example":".demo {\n  position: absolute;\n  left: 50%;\n  transform: translateX(-50%);\n}","notes":["static 定位下 left 不生效。","left 与 right 都设置且 width: auto 时元素宽度被拉伸。"],"syntax":"auto | <length-percentage> | <anchor()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块宽度","appliesTo":"定位元素","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Anchor Positioning","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/left","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"left","order":390},{"name":"position","js":"position","zh":"定位方式","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"选择元素参与布局的定位方案","description":"五个关键字对应不同参考系：static 为默认正常流；relative 相对自身原位偏移但仍占原位；absolute 相对最近的非 static 祖先定位并脱离文档流；fixed 相对视口（祖先含 transform 等属性时改为相对该祖先）；sticky 滚动到阈值前保持正常流，之后粘附。除 static 外可使用 z-index 并创建层叠上下文。","aliases":["定位","position","定位方式","定位模式"],"keywords":["定位","布局","层叠","吸顶"],"values":[{"v":"static","d":"初始值，正常流布局，偏移属性与 z-index 无效。"},{"v":"relative","d":"相对定位，相对自身原位置偏移，仍保留原有占位。"},{"v":"absolute","d":"绝对定位，脱离文档流，相对最近的非 static 祖先定位。"},{"v":"fixed","d":"固定定位，相对视口定位，滚动时位置不变。"},{"v":"sticky","d":"粘性定位，滚动到指定阈值后吸附在容器内。"}],"example":".demo {\n  position: sticky;\n  top: 0;\n  background: #fff;\n}","notes":["absolute 的参照是最近的非 static 祖先，父级忘了设定位是常见坑。","祖先带 transform、filter、will-change 时 fixed 会改为相对该祖先定位。"],"syntax":"static | relative | absolute | sticky | fixed","initial":"static","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"position","order":504},{"name":"reading-flow","js":"readingFlow","zh":"阅读流顺序","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"让无障碍阅读顺序跟随视觉布局顺序","description":"用于解决 flex/grid 中 row-reverse、order 或网格排列导致视觉顺序与 DOM 顺序不一致的问题：设置后屏幕阅读器与 Tab 键按视觉顺序遍历子元素。normal 保持源顺序，flex-visual 按弹性顺序，grid-rows 与 grid-columns 按网格行列，source-order 回到源顺序。属新特性，需确认兼容性。","aliases":["阅读流","阅读顺序","reading-flow","焦点顺序"],"keywords":["无障碍","顺序","布局","焦点"],"values":[{"v":"normal","d":"初始值，阅读顺序与 DOM 源顺序一致。"},{"v":"source-order","d":"强制使用源顺序，忽略视觉重排。"},{"v":"flex-visual","d":"按弹性项目的视觉排列顺序阅读。"},{"v":"grid-rows","d":"按网格行方向逐行遍历。"},{"v":"grid-columns","d":"按网格列方向逐列遍历。"},{"v":"grid-order","d":"按网格项被 order 调整后的顺序遍历。"}],"example":".demo {\n  display: grid;\n  reading-flow: grid-rows;\n}","notes":["Chrome 137 起支持，Firefox 与 Safari 暂不支持，需渐进增强。","它不改变 DOM 顺序和视觉位置，只影响阅读与焦点遍历顺序。"],"syntax":"normal | source-order | flex-visual | flex-flow | grid-rows | grid-columns | grid-order","initial":"normal","inherited":"否","animation":"不可动画","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"按指定值","specGroups":["CSS Display"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/reading-flow","browser":{"chrome":"137","firefox":"✗","safari":"✗","edge":"137"},"tier":"core","tags":[],"id":"reading-flow","order":514},{"name":"reading-order","js":"readingOrder","zh":"阅读顺序权重","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"调整阅读流中元素的遍历先后次序","description":"配合 reading-flow 使用，给子元素一个整数权重，数值小的先被阅读与聚焦，默认 0，可正可负。它只影响无障碍与 Tab 顺序，不改变元素在页面上的视觉效果，因此比用 order 重排内容更安全，不会出现视觉与阅读顺序错位。属于较新特性，目前仅部分浏览器实现。","aliases":["阅读顺序权重","reading-order","焦点顺序"],"keywords":["无障碍","顺序","焦点","权重"],"values":[{"v":"0","d":"初始值，按源顺序或 reading-flow 规则排列。"},{"v":"<integer>","d":"任意整数，值越小越靠前，可为负数。"}],"example":".demo {\n  display: flex;\n  reading-flow: flex-visual;\n  reading-order: 1;\n}","notes":["需要父级设置 reading-flow 才能发挥排序作用。","Chrome 137 起支持，其他主流浏览器尚未跟进。"],"syntax":"<integer>","initial":"0","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"块级、弹性、网格容器","computed":"见规范","specGroups":["CSS Display"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/reading-order","browser":{"chrome":"137","firefox":"✗","safari":"✗","edge":"137"},"tier":"core","tags":["可动画"],"id":"reading-order","order":515},{"name":"right","js":"right","zh":"右侧偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"设置定位元素右边缘相对包含块的偏移","description":"指定定位元素右边缘相对包含块右侧的距离，百分比基于包含块宽度。relative 下是相对原位的位移并保留占位；absolute 与 fixed 下参与定位计算，常与 top 搭配做右上角角标。right 与 left 同时设置且 width 为 auto 时会拉伸宽度。多语言镜像场景建议用逻辑属性 inset-inline-end 替代。","aliases":["右侧偏移","右偏移","right offset","right"],"keywords":["定位","偏移","左右","布局"],"values":[{"v":"auto","d":"初始值，由浏览器按定位规则计算。"},{"v":"<length>","d":"长度值，如 0、16px、-4px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"<anchor()>","d":"锚点定位函数，对齐指定锚点的右边缘，属较新特性。"}],"example":".demo {\n  position: absolute;\n  top: 0;\n  right: 0;\n}","notes":["静态定位元素设置 right 无效。","需要随语言镜像时改用 inset-inline-end。"],"syntax":"auto | <length-percentage> | <anchor()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块宽度","appliesTo":"定位元素","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Anchor Positioning","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/right","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"right","order":517},{"name":"top","js":"top","zh":"顶部偏移","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"设置定位元素上边缘相对包含块的偏移","description":"指定定位元素上边缘相对包含块顶部的距离，百分比相对包含块高度。sticky 定位中最常用，用来设定开始粘附的阈值；absolute 下与 left/right 组合定位；relative 下产生视觉位移但保留原有占位。与 bottom 同时设置且 height: auto 时会拉伸元素高度。","aliases":["顶部偏移","上偏移","top offset","top"],"keywords":["定位","偏移","吸顶","上下"],"values":[{"v":"auto","d":"初始值，由浏览器按定位规则计算。"},{"v":"<length>","d":"长度值，如 0、32px、-12px。"},{"v":"<percentage>","d":"相对包含块高度的百分比。"},{"v":"<anchor()>","d":"锚点定位函数，让上边缘对齐锚点，属较新特性。"}],"example":".demo {\n  position: sticky;\n  top: 1rem;\n}","notes":["sticky 至少需要设置一个方向的偏移值才会产生粘附效果。","top 与 bottom 同时设置且 height: auto 时元素高度被拉伸。"],"syntax":"auto | <length-percentage> | <anchor()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块高度","appliesTo":"定位元素","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Anchor Positioning","CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/top","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"top","order":632},{"name":"z-index","js":"zIndex","zh":"层叠顺序","category":"layout","categoryName":"布局与定位","status":"standard","statusLabel":"标准","summary":"控制元素在同层叠上下文中的堆叠先后","description":"用整数决定同一层叠上下文内元素的堆叠顺序，数值大的显示在上层，auto 表示不新建层叠层级、随父级处理。只对定位元素、flex/grid 子项等生效。最常见的坑是父元素已创建层叠上下文（如 position 配合 z-index、transform、opacity 小于 1），此时子元素再大的 z-index 也只能在父级的层级内部比较。","aliases":["层级","层叠顺序","zIndex","z-index"],"keywords":["层叠","层级","定位","覆盖"],"values":[{"v":"auto","d":"初始值，与父级同层，不参与整数排序。"},{"v":"<integer>","d":"任意整数，越大越靠上，可为负数。"}],"example":".demo {\n  position: absolute;\n  z-index: 10;\n}","notes":["父元素形成层叠上下文后，子元素的 z-index 只在父级内部比较。","静态元素设置 z-index 通常无效，除非它是 flex/grid 子项。"],"syntax":"auto | <integer>","initial":"auto","inherited":"否","animation":"整数插值","percentages":"不适用","appliesTo":"定位元素","computed":"按指定值","specGroups":["CSS Positioned Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/z-index","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"z-index","order":670},{"name":"anchor-name","js":"anchorName","zh":"锚点名称","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"给元素命名以便被锚点定位引用","description":"CSS 锚点定位的入口属性：用 dashed-ident（以两个短横线开头的自定义标识）给元素命名，之后绝对定位元素可通过 position-anchor 或 anchor() 函数引用它，实现跟随按钮的气泡提示、下拉菜单等布局。可写多个名称，同名锚点以文档中靠后的元素为准。属于实验特性，生产环境需准备降级方案。","aliases":["锚点名称","anchor-name","CSS 锚点"],"keywords":["锚点定位","定位","气泡","实验特性"],"values":[{"v":"none","d":"初始值，不定义锚点名称。"},{"v":"<dashed-ident>","d":"以 -- 开头的自定义标识，如 --my-anchor。"},{"v":"<dashed-ident>#","d":"多个名称用逗号分隔，可被不同定位引用。"}],"example":".demo {\n  anchor-name: --btn-anchor;\n}","notes":["实验性特性，旧浏览器会忽略，需要时用 JS 兜底定位。","同名锚点以树序靠后的元素生效，避免重复命名。"],"syntax":"none | <dashed-ident>#","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"生成主体盒的所有元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/anchor-name","browser":{"chrome":"125","firefox":"147","safari":"26","edge":"125"},"tier":"extra","tags":["可动画","实验性"],"id":"anchor-name","order":119},{"name":"anchor-scope","js":"anchorScope","zh":"锚点作用域","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"限定锚点名称可被引用的范围","description":"控制锚点名称对哪些元素可见。none 表示不做作用域限制；all 或指定名称列表把锚点名的可见范围限制在当前元素子树内，用于避免组件列表中多个同名锚点相互干扰，例如每张卡片都定义 --card-anchor 时，作用域能保证各自引用自己的锚点。属于实验特性，兼容性有限。","aliases":["锚点作用域","anchor-scope","锚点范围"],"keywords":["锚点定位","作用域","组件","实验特性"],"values":[{"v":"none","d":"初始值，不限制锚点名称的作用范围。"},{"v":"all","d":"当前子树内定义的所有锚点名都限制在本元素内。"},{"v":"<dashed-ident>#","d":"只限定列出的锚点名称，多个用逗号分隔。"}],"example":".demo {\n  anchor-scope: --card-anchor;\n}","notes":["实验特性，浏览器支持较新，应作为增强而非依赖。","主要用于列表或组件内多个同名锚点的隔离。"],"syntax":"none | all | <dashed-ident>#","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"","browser":{"chrome":"131","firefox":"147","safari":"26","edge":"131"},"tier":"extra","tags":["可动画","实验性"],"id":"anchor-scope","order":120},{"name":"position-anchor","js":"positionAnchor","zh":"默认锚点","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"为绝对定位元素指定默认引用的锚点","description":"为绝对定位元素设置默认锚点，之后 position-area、position-try-fallbacks 以及省略名称的 anchor() 都会指向它。取值可为 normal（初始值，按常规行为处理）、auto（沿用父元素的默认锚点）、none（不引用锚点）或 anchor-name 定义过的名称。一个元素只能有一个默认锚点。","aliases":["默认锚点","position-anchor","锚点引用"],"keywords":["锚点定位","定位","气泡","实验特性"],"values":[{"v":"normal / auto","d":"normal 为初始值；auto 沿用父元素的默认锚点。"},{"v":"none","d":"显式声明不引用任何锚点。"},{"v":"<anchor-name>","d":"引用由 anchor-name 定义的锚点名称，如 --btn-anchor。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-area: bottom;\n}","notes":["实验性特性，需较新浏览器，常与 position-area、position-try 搭配。","该属性只对绝对定位元素有效。"],"syntax":"normal | auto | none | <anchor-name> | match-parent","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"绝对定位元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-anchor","browser":{"chrome":"151","firefox":"151","safari":"27","edge":"151"},"tier":"extra","tags":["可动画","实验性"],"id":"position-anchor","order":505},{"name":"position-area","js":"positionArea","zh":"锚点方位区域","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"按九宫格方位把元素放到锚点旁边","description":"用 3×3 网格方位描述元素相对锚点的放置区域，例如 bottom 表示放在锚点正下方，bottom span-right 表示从下方跨到右侧。它替代手写 anchor() 偏移计算，让气泡与下拉菜单的摆放更直观。需要元素已通过 position-anchor 指定默认锚点。属于实验特性，旧浏览器会忽略该声明。","aliases":["锚点区域","position-area","九宫格定位"],"keywords":["锚点定位","气泡","定位","实验特性"],"values":[{"v":"none","d":"初始值，不使用方位区域定位。"},{"v":"top / bottom / left / right / center","d":"放在锚点某一侧，center 表示居中对齐锚点。"},{"v":"<span 组合>","d":"跨两格，如 bottom span-right，从下方跨到右侧。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-area: bottom;\n}","notes":["实验特性，旧版本浏览器会忽略整条声明，需要降级定位。","依赖 position-anchor 指定默认锚点。"],"syntax":"none | <position-area>","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"带默认锚点元素的定位元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-area","browser":{"chrome":"129","firefox":"147","safari":"26","edge":"129"},"tier":"extra","tags":["可动画","实验性"],"id":"position-area","order":506},{"name":"position-try","js":"positionTry","zh":"定位回退简写","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"同时设置定位回退顺序与回退方案","description":"position-try-order 与 position-try-fallbacks 的简写，当默认位置被视口或容器裁剪时，按方案列表依次尝试备选位置，让弹层自动翻转或换边显示。例如 position-try: flip-block 会在下方空间不足时翻到上方。使用前需已指定默认锚点。属于实验特性，生产环境应保留 JS 兜底。","aliases":["定位回退","position-try","回退简写"],"keywords":["锚点定位","回退","弹层","实验特性"],"values":[{"v":"<'position-try-order'>? <'position-try-fallbacks'>","d":"顺序值可选，方案值为必填，如 flip-block。"},{"v":"none","d":"等价于不回退，保持默认位置。"},{"v":"flip-block / flip-inline","d":"常见翻转策略：块向或行向对侧翻转。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-try: flip-block;\n}","notes":["实验特性，旧浏览器忽略声明但不报错。","简写展开为 position-try-order 与 position-try-fallbacks。"],"syntax":"<'position-try-order'>? <'position-try-fallbacks'>","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"绝对定位元素","computed":"由各长写属性决定","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-try","browser":{"chrome":"125","firefox":"147","safari":"26","edge":"125"},"tier":"extra","tags":["可动画","实验性","简写"],"id":"position-try","order":507},{"name":"position-try-fallbacks","js":"positionTryFallbacks","zh":"定位回退方案","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"列出位置不足时依次尝试的备选定位","description":"定义一组回退方案，浏览器在当前摆放会溢出时按顺序尝试，直到找到完全可见的方案。可以写 flip-block、flip-inline、flip-start 等翻转策略，也可以引用 @position-try 定义的具名方案，多个用逗号分隔。它与 position-try-order 配合决定评估优先级。属于实验特性，支持范围较新。","aliases":["回退方案","position-try-fallbacks","定位回退列表"],"keywords":["锚点定位","回退","弹层","实验特性"],"values":[{"v":"none","d":"初始值，不做回退尝试。"},{"v":"<try-tactic>","d":"翻转策略或方位区域，如 flip-block、bottom；多个用逗号分隔。"},{"v":"<dashed-ident>","d":"引用 @position-try 定义的具名方案，如 --my-try。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-try-fallbacks: flip-block, flip-inline;\n}","notes":["实验特性，浏览器支持较新，旧版本忽略整条声明。","方案按书写顺序依次评估，顺序会影响最终落点。"],"syntax":"none | [ [<dashed-ident> || <try-tactic>] | <'position-area'> ]#","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"绝对定位元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-try-fallbacks","browser":{"chrome":"128","firefox":"147","safari":"26","edge":"128"},"tier":"extra","tags":["可动画","实验性"],"id":"position-try-fallbacks","order":508},{"name":"position-try-order","js":"positionTryOrder","zh":"回退尝试顺序","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"决定回退方案按什么优先顺序评估","description":"控制 position-try-fallbacks 中方案的评估顺序。normal 按声明顺序尝试；most-block-size、most-height、most-width、most-inline-size 等值让浏览器优先选择能获得更多空间的方案。适合长列表下拉菜单在空间不足时选择更宽松的一侧展开。属于实验特性，兼容性有限。","aliases":["回退顺序","position-try-order","尝试顺序"],"keywords":["锚点定位","回退","优先级","实验特性"],"values":[{"v":"normal","d":"初始值，按方案声明顺序依次尝试。"},{"v":"most-block-size / most-inline-size","d":"优先选择块向或行向可用空间最大的方案。"},{"v":"most-height / most-width","d":"按物理高度或宽度选择空间最大的方案。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-try-order: most-block-size;\n}","notes":["实验特性，需较新浏览器支持。","仅影响方案评估优先级，不改变方案本身。"],"syntax":"normal | <try-size>","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"绝对定位元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-try-order","browser":{"chrome":"125","firefox":"148","safari":"26","edge":"125"},"tier":"extra","tags":["可动画","实验性"],"id":"position-try-order","order":509},{"name":"position-visibility","js":"positionVisibility","zh":"定位可见性","category":"layout","categoryName":"布局与定位","status":"experimental","statusLabel":"实验性","summary":"控制锚点不可见时定位元素的显示","description":"用于锚点定位元素：当锚点被滚动出视口、被移除或无效时，决定是否继续显示。always 始终显示；anchors-visible 在锚点不可见时隐藏（初始值）；anchors-valid 在锚点无效时隐藏；no-overflow 在元素会被容器裁剪时隐藏。它能减少滚动容器中气泡跑到屏幕外或错位的问题。属于实验特性。","aliases":["定位可见性","position-visibility","锚点可见性"],"keywords":["锚点定位","可见性","弹层","实验特性"],"values":[{"v":"always","d":"无论锚点状态如何都显示。"},{"v":"anchors-visible","d":"初始值，锚点不可见时隐藏该元素。"},{"v":"anchors-valid / no-overflow","d":"锚点无效时隐藏，或元素被容器裁剪时隐藏。"}],"example":".demo {\n  position: absolute;\n  position-anchor: --btn-anchor;\n  position-visibility: anchors-visible;\n}","notes":["实验特性，浏览器实现较新，需准备降级方案。","适合滚动容器内的气泡提示，避免锚点滚出后仍漂浮显示。"],"syntax":"always | [ anchors-valid || anchors-visible || no-overflow ]","initial":"anchors-visible","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"绝对定位元素","computed":"按指定值","specGroups":["CSS Anchor Positioning"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-visibility","browser":{"chrome":"125","firefox":"147","safari":"26.2","edge":"125"},"tier":"extra","tags":["可动画","实验性"],"id":"position-visibility","order":510},{"name":"align-content","js":"alignContent","zh":"多行内容对齐","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"在多行或多轨容器中沿交叉轴分配空间","description":"为弹性多行、网格行/列轨道以及块级容器分配交叉轴上的剩余空间：center 居中、space-between/around/evenly 按不同规则分散、stretch 拉伸。在单行弹性容器中通常看不出效果（需配合 flex-wrap: wrap），网格中若轨道已占满也没有可分配空间。取值语义与 justify-content 完全对称，只是作用轴不同。","aliases":["内容对齐","多行对齐","align-content","交叉轴分配"],"keywords":["对齐","弹性","网格","多行"],"values":[{"v":"normal","d":"初始值，行为与 stretch 类似。"},{"v":"stretch","d":"拉伸轨道或多行以填满容器。"},{"v":"center","d":"整体居中，剩余空间平均分配到两侧。"},{"v":"space-between","d":"首尾贴边，剩余空间均匀分布在行或轨道之间。"},{"v":"space-around","d":"每行两侧留等量空间，行间是两端的两倍。"},{"v":"space-evenly","d":"所有间隙完全相等。"},{"v":"flex-start / flex-end","d":"靠交叉轴起始或结束侧对齐。"}],"example":".demo {\n  display: flex;\n  flex-wrap: wrap;\n  align-content: center;\n}","notes":["单行弹性容器中 align-content 无效，应改用 align-items。","网格容器中作用于行轨道的空间分配。"],"syntax":"normal | <baseline-position> | <content-distribution> | <overflow-position>? <content-position>","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级、多列、弹性、网格容器","computed":"按指定值","specGroups":["CSS Box Alignment","CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/align-content","browser":{"chrome":"29","firefox":"28","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"align-content","order":113},{"name":"align-items","js":"alignItems","zh":"项目交叉轴对齐","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"统一设置容器内项目在交叉轴上的对齐","description":"作用于弹性或网格容器，统一设置子项在交叉轴上的对齐方式：stretch 拉伸填满交叉轴、center 居中、flex-start/flex-end 靠边、baseline 按首行文字基线对齐。它是容器属性，写在容器上而不是项目上；单个项目想覆盖时使用 align-self。垂直居中常用 align-items: center。","aliases":["交叉轴对齐","项目对齐","align-items","垂直居中"],"keywords":["对齐","弹性","网格","居中"],"values":[{"v":"normal","d":"初始值，多数场景表现为 stretch。"},{"v":"stretch","d":"项目拉伸填满交叉轴，项目有固定尺寸时不生效。"},{"v":"center","d":"在交叉轴上居中。"},{"v":"flex-start / flex-end","d":"靠交叉轴起始或结束侧对齐。"},{"v":"baseline","d":"按项目首行文字的基线对齐。"},{"v":"anchor-center","d":"锚点定位下相对锚点居中，较新特性。"}],"example":".demo {\n  display: flex;\n  align-items: center;\n  min-height: 120px;\n}","notes":["它是容器属性，需写在 flex/grid 容器上。","子项可用 align-self 单独覆盖。"],"syntax":"normal | stretch | <baseline-position> | [ <overflow-position>? <self-position> ] | anchor-center","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Box Alignment","CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/align-items","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"align-items","order":114},{"name":"align-self","js":"alignSelf","zh":"单项交叉轴对齐","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"单独覆盖某个项目在交叉轴上的对齐","description":"作用于弹性与网格项目以及绝对定位盒子，用于单独覆盖父容器 align-items 的设置。auto 表示继承容器的 align-items，其余取值与 align-items 一致。常见场景是让某个按钮在标题行里顶部对齐而不影响其他元素。它写在项目上，对普通块级子元素无效。","aliases":["单独对齐","align-self","项目对齐覆盖"],"keywords":["对齐","弹性","网格","覆盖"],"values":[{"v":"auto","d":"初始值，沿用父容器的 align-items 值。"},{"v":"stretch","d":"拉伸填满交叉轴。"},{"v":"center","d":"在交叉轴上居中。"},{"v":"flex-start / flex-end","d":"靠交叉轴起始或结束侧对齐。"},{"v":"baseline","d":"按文字基线对齐。"}],"example":".demo {\n  align-self: flex-end;\n}","notes":["只对弹性/网格项目或绝对定位盒子有效。","auto 不是「无对齐」，而是继承父容器设置。"],"syntax":"auto | normal | stretch | <baseline-position> | <overflow-position>? <self-position> | anchor-center","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"弹性项目、网格项目与绝对定位盒","computed":"绝对定位元素上为 auto，否则取父级 align-items","specGroups":["CSS Box Alignment","CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/align-self","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"align-self","order":115},{"name":"flex","js":"flex","zh":"弹性简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置伸缩比、收缩比与基准尺寸","description":"flex-grow、flex-shrink、flex-basis 的简写。常用单值：flex: 1 展开为 1 1 0%，自适应占满剩余空间；flex: auto 展开为 1 1 auto，按内容大小再分配；flex: none 展开为 0 0 auto，不伸不缩。坑是省略 flex-basis 时按 0% 而非 auto 计算，与手写长写属性结果不同。","aliases":["弹性","flex","伸缩简写","弹性布局"],"keywords":["弹性","简写","伸缩","布局"],"values":[{"v":"none","d":"等价于 0 0 auto，项目不伸缩，尺寸由内容决定。"},{"v":"auto","d":"等价于 1 1 auto，按内容宽度分配剩余空间。"},{"v":"<number>","d":"只写一个数字时为 flex-grow，其余按 1 1 0% 补全，如 flex: 1。"},{"v":"<grow> <shrink>","d":"如 flex: 1 0，只设伸缩比与收缩比。"},{"v":"<grow> <shrink> <basis>","d":"完整写法，如 flex: 0 1 200px。"},{"v":"<basis>","d":"只写长度或百分比时作为 flex-basis，如 flex: 30%。"}],"example":".demo {\n  flex: 1;\n  min-width: 0;\n}","notes":["flex: 1 的基准值是 0%，不是 auto，两者分配结果不同。","项目内容溢出不收缩时，给项目加 min-width: 0。"],"syntax":"none | [ <'flex-grow'> <'flex-shrink'>? || <'flex-basis'> ]","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"弹性项目与参与常规流的伪元素","computed":"由各长写属性决定","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex","browser":{"chrome":"29","firefox":"22","safari":"9","edge":"12"},"tier":"core","tags":["可动画","简写"],"id":"flex","order":301},{"name":"flex-basis","js":"flexBasis","zh":"弹性基准尺寸","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置弹性项目分配空间前的初始主轴尺寸","description":"决定项目在分配剩余空间之前的初始主轴尺寸：auto 表示取 width/height（或内容尺寸），content 表示按内容大小，也可写长度或百分比。在弹性项目中它会覆盖 width 作为主轴尺寸，因此调宽时优先检查 flex-basis 是否被 flex 简写设成 0%。它是 flex 简写的第三个组成部分。","aliases":["基准尺寸","flex-basis","弹性基准","主轴尺寸"],"keywords":["弹性","尺寸","主轴","伸缩"],"values":[{"v":"auto","d":"初始值，取 width/height，未设置时按内容尺寸。"},{"v":"content","d":"按内容自身尺寸计算基准。"},{"v":"<length>","d":"固定长度，如 200px、12rem。"},{"v":"<percentage>","d":"相对弹性容器主轴内尺寸的百分比。"},{"v":"0","d":"基准为 0，项目尺寸完全由伸缩比分配。"}],"example":".demo {\n  flex-basis: 240px;\n  flex-grow: 0;\n  flex-shrink: 1;\n}","notes":["弹性项目中 flex-basis 的优先级高于主轴上的 width。","百分比相对弹性容器的主轴尺寸解析。"],"syntax":"content | <'width'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对弹性容器内部主轴尺寸","appliesTo":"弹性项目与参与常规流的伪元素","computed":"按指定值，长度转为绝对值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-basis","browser":{"chrome":"29","firefox":"22","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"flex-basis","order":302},{"name":"flex-direction","js":"flexDirection","zh":"弹性主轴方向","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"决定弹性项目排列的主轴方向","description":"设置弹性容器的主轴方向：row 水平自左向右（默认）、row-reverse 水平反向、column 垂直自上而下、column-reverse 垂直反向。它还决定主轴与交叉轴的对应关系，因此改变方向会连带改变 justify-content 与 align-items 的作用轴，是排查弹性布局对齐不生效时的首要检查项。","aliases":["主轴方向","flex-direction","排列方向","弹性方向"],"keywords":["弹性","方向","主轴","布局"],"values":[{"v":"row","d":"初始值，主轴水平，项目自左向右排列。"},{"v":"row-reverse","d":"主轴水平，项目自右向左排列。"},{"v":"column","d":"主轴垂直，项目自上而下排列。"},{"v":"column-reverse","d":"主轴垂直，项目自下而上排列。"}],"example":".demo {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}","notes":["reverse 只改变视觉顺序，DOM 与 Tab 顺序不变。","改为 column 后 justify-content 与 align-items 的作用轴会互换。"],"syntax":"row | row-reverse | column | column-reverse","initial":"row","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"弹性容器","computed":"按指定值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-direction","browser":{"chrome":"29","firefox":"22","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"flex-direction","order":303},{"name":"flex-flow","js":"flexFlow","zh":"弹性流向简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置主轴方向与是否换行","description":"flex-direction 与 flex-wrap 的简写，两个值顺序可互换，flex-flow: wrap column 与 column wrap 等价。常用 row wrap 实现自动换行的水平列表，column nowrap 明确竖排且不换行。它是容器属性，用一条声明替代两行长写，注意它不是 flex 的简写、不涉及伸缩比例。","aliases":["流向简写","flex-flow","弹性流向"],"keywords":["弹性","简写","换行","方向"],"values":[{"v":"row / column","d":"设置主轴方向，与 flex-direction 取值一致。"},{"v":"row-reverse / column-reverse","d":"反向排列的主轴方向。"},{"v":"nowrap","d":"初始换行值，项目不换行，可能溢出或被压缩。"},{"v":"wrap / wrap-reverse","d":"允许换行，wrap-reverse 让换行方向相反。"},{"v":"<direction> <wrap>","d":"两个值顺序无关，如 row wrap。"}],"example":".demo {\n  display: flex;\n  flex-flow: row wrap;\n  gap: 8px;\n}","notes":["两个关键字顺序可互换，浏览器按类型识别。","与 flex 简写无关，flex-flow 只涉及方向与换行。"],"syntax":"<'flex-direction'> || <'flex-wrap'>","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"弹性容器","computed":"由各长写属性决定","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-flow","browser":{"chrome":"29","firefox":"28","safari":"9","edge":"12"},"tier":"core","tags":["可动画","简写"],"id":"flex-flow","order":304},{"name":"flex-grow","js":"flexGrow","zh":"放大比例","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置弹性项目分配剩余空间的放大权重","description":"定义项目的放大系数：容器有剩余空间时，按各项目 flex-grow 的比例分配这些空间。初始值 0 表示不放大，数值越大分得越多，全部为 1 时平均分配。它只参与正剩余空间的分配，不会让项目小于 flex-basis；它是 flex 简写的第一个数值，例如 flex: 2 1 auto。","aliases":["放大系数","放大比例","flex-grow","伸展比"],"keywords":["弹性","伸缩","空间分配","布局"],"values":[{"v":"<number>","d":"非负数值，按比例分享剩余空间，如 1、2.5。"},{"v":"0","d":"初始值，项目不放大，保持基准尺寸。"},{"v":"1","d":"常用值，与其他为 1 的项目平分剩余空间。"}],"example":".demo {\n  flex-grow: 2;\n  flex-basis: 0;\n}","notes":["所有项目 flex-grow 都为 0 时，剩余空间会保留而不被分配。","它是 flex 简写中数值部分的第一个参数。"],"syntax":"<number>","initial":"0","inherited":"否","animation":"数值插值","percentages":"不适用","appliesTo":"弹性项目与参与常规流的伪元素","computed":"按指定值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-grow","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"flex-grow","order":305},{"name":"flex-line-count","js":"flexLineCount","zh":"弹性行数","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"限制多行弹性容器生成的弹性行数量","description":"弹性盒布局较新的属性，用于限制允许换行的弹性容器最终生成多少条弹性行，取值为 1 或更大的整数，初始值 1。它适合标签云、筛选条这类需要限制折行层数的场景，需配合 flex-wrap 允许换行才有意义。目前仅 Chrome 150 起实现，Firefox 与 Safari 尚未支持，属前沿特性。","aliases":["弹性行数","flex-line-count","限制行数"],"keywords":["弹性","换行","行数","前沿特性"],"values":[{"v":"<integer [1,∞]>","d":"不小于 1 的整数，表示最多生成的弹性行数。"},{"v":"1","d":"初始值，即只保留一条弹性行。"}],"example":".demo {\n  display: flex;\n  flex-wrap: wrap;\n  flex-line-count: 2;\n}","notes":["Chrome 150 起支持，Firefox 与 Safari 尚未实现。","需配合 flex-wrap 允许换行才有意义。"],"syntax":"<integer [1,∞]>","initial":"1","inherited":"否","animation":"数值插值","percentages":"不适用","appliesTo":"多行弹性容器","computed":"按指定值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-line-count","browser":{"chrome":"150","firefox":"✗","safari":"✗","edge":"150"},"tier":"core","tags":["可动画"],"id":"flex-line-count","order":306},{"name":"flex-shrink","js":"flexShrink","zh":"收缩比例","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置空间不足时弹性项目的收缩权重","description":"定义项目的收缩系数：容器空间不足时，各项目按 flex-shrink 与 flex-basis 的加权结果决定各自让出多少空间。初始值 1 表示允许收缩，设为 0 则项目保持基准尺寸不被压缩，常用于固定宽度的图标、头像或按钮。收缩的下限通常受 min-content 限制，必要时需显式设置 min-width: 0。","aliases":["收缩系数","收缩比例","flex-shrink","压缩比"],"keywords":["弹性","收缩","空间分配","布局"],"values":[{"v":"<number>","d":"非负数值，值越大让出空间越多。"},{"v":"1","d":"初始值，允许按比例收缩。"},{"v":"0","d":"禁止收缩，空间不足时保持基准尺寸。"}],"example":".demo {\n  flex-shrink: 0;\n  width: 120px;\n}","notes":["默认不会收缩到小于内容最小宽度，需要时显式写 min-width: 0。","固定尺寸元素常设 flex-shrink: 0 防止被挤扁。"],"syntax":"<number>","initial":"1","inherited":"否","animation":"数值插值","percentages":"不适用","appliesTo":"弹性项目与参与常规流的伪元素","computed":"按指定值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-shrink","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"flex-shrink","order":307},{"name":"flex-wrap","js":"flexWrap","zh":"弹性换行","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"控制弹性项目一行放不下时是否换行","description":"决定弹性容器内容溢出主轴时是否折行。nowrap 为初始值，项目被压缩或溢出到容器外；wrap 允许换行且新行依次向后排列；wrap-reverse 让换行方向反转。只有允许换行时容器才可能有多行，align-content 与 flex-line-count 也才有作用对象。较新的 balance 关键字用于让各行项目数量更均衡。","aliases":["换行","弹性换行","flex-wrap","折行"],"keywords":["弹性","换行","溢出","布局"],"values":[{"v":"nowrap","d":"初始值，不换行，项目被压缩可能溢出。"},{"v":"wrap","d":"允许换行，新行按主轴方向依次排列。"},{"v":"wrap-reverse","d":"允许换行，但行顺序反转。"},{"v":"balance","d":"较新关键字，让各行项目数量尽量均衡，支持有限。"}],"example":".demo {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}","notes":["nowrap 时长文本可能撑破容器或被截断。","允许换行后 align-content 才能发挥作用。","balance 为较新关键字，旧浏览器会忽略。"],"syntax":"nowrap | [ wrap | wrap-reverse ] || balance","initial":"nowrap","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"弹性容器","computed":"按指定值","specGroups":["CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-wrap","browser":{"chrome":"29","firefox":"28","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"flex-wrap","order":308},{"name":"gap","js":"gap","zh":"间距简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置行列之间的空隙间距","description":"row-gap 与 column-gap 的简写，用于弹性、网格与多列布局，只在项目之间产生间距，不会在容器首尾额外留白，因此比用 margin 拼间距更干净。写一个值时行列间距相同，两个值时依次为行间距、列间距。网格中百分比相对内容盒尺寸解析，弹性布局中的百分比支持较新。","aliases":["间距","网格间距","gap","行列间距"],"keywords":["间距","网格","弹性","简写"],"values":[{"v":"<length>","d":"固定间距，如 16px、1rem，也可为 0。"},{"v":"<percentage>","d":"相对尺寸的百分比，网格中相对内容盒。"},{"v":"normal","d":"初始值，一般计算为 0（多列布局另有规则）。"},{"v":"<row> <column>","d":"两个值时依次为行间距与列间距，如 8px 16px。"}],"example":".demo {\n  display: grid;\n  gap: 16px 24px;\n}","notes":["gap 只作用于项目之间，容器首尾不会多出空白。","旧写法 grid-gap 已被 gap 取代。"],"syntax":"<'row-gap'> <'column-gap'>?","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"多列元素、弹性容器、网格容器","computed":"由各长写属性决定","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/gap","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"gap","order":342},{"name":"grid","js":"grid","zh":"网格简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"一次性设置网格模板与自动布局规则","description":"最完整的网格简写，可同时设置网格模板、自动行列尺寸、自动流与行列间距。如 grid: 100px 1fr / 1fr 2fr 写模板，grid: auto-flow 120px / repeat(3, 1fr) 写自动流形式。它会把未写出的子属性按简写规则重置，容易误覆盖已有设置，排查问题时应优先检查。","aliases":["网格","grid","网格简写","网格布局"],"keywords":["网格","简写","布局","模板"],"values":[{"v":"<'grid-template'>","d":"模板形式，如 60px 1fr / 200px 1fr。"},{"v":"<rows> / auto-flow <cols>","d":"行模板加自动流，如 100px / auto-flow 80px。"},{"v":"auto-flow <rows> / <columns>","d":"先声明自动流再给列模板，如 auto-flow 120px / repeat(3, 1fr)。"},{"v":"dense","d":"附加在 auto-flow 之后，启用密排回填空洞。"}],"example":".demo {\n  display: grid;\n  grid: auto-flow 120px / repeat(3, 1fr);\n}","notes":["简写会把未写出的子属性重置，可能悄悄覆盖之前的模板或间距。","需要只改模板时用 grid-template 更安全。"],"syntax":"<'grid-template'> | <'grid-template-rows'> / [ auto-flow && dense? ] <'grid-auto-columns'>? | [ auto-flow && dense? ] <'grid-auto-rows'>? / <'grid-template-columns'>","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"网格容器","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"grid","order":343},{"name":"grid-area","js":"gridArea","zh":"网格区域","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"用一条声明指定网格项占据的行列区域","description":"grid-row-start、grid-column-start、grid-row-end、grid-column-end 的简写，值用斜杠分隔，顺序为行起、列起、行止、列止。除网格线编号外还可直接写模板定义的区域名，如 grid-area: header 即可落到同名区域。漏写的结束值默认为 auto，此时项目只占一格。","aliases":["网格区域","grid-area","区域定位"],"keywords":["网格","简写","区域","定位"],"values":[{"v":"<name>","d":"区域名，需与 grid-template-areas 中定义的一致，如 header。"},{"v":"<row-start> / <col-start> / <row-end> / <col-end>","d":"四个网格线值用斜杠分隔，如 1 / 1 / 3 / 3。"},{"v":"auto","d":"省略的结束线为 auto，自动推断跨度。"},{"v":"span <integer>","d":"表示跨越若干条轨道，如 span 2。"}],"example":".demo {\n  grid-area: 1 / 1 / 3 / 3;\n}","notes":["顺序是行起 / 列起 / 行止 / 列止，注意与写行列的直觉相反。","直接写区域名最直观，需配合 grid-template-areas。"],"syntax":"<grid-line> [ / <grid-line> ]{0,3}","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-area","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"grid-area","order":344},{"name":"grid-auto-columns","js":"gridAutoColumns","zh":"自动列尺寸","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置隐式生成的网格列轨道尺寸","description":"当网格项被放到 grid-template-columns 定义范围之外时，浏览器会自动创建隐式列，本属性决定这些列的宽度。可取 auto、固定长度、百分比、min-content、max-content 或 minmax()，写多个值则循环用于连续的隐式列。它只影响隐式列，显式模板列由 grid-template-columns 控制。","aliases":["自动列宽","grid-auto-columns","隐式列尺寸"],"keywords":["网格","隐式轨道","列宽","自动布局"],"values":[{"v":"auto","d":"初始值，由内容与可用空间自动决定列宽。"},{"v":"<length>","d":"固定宽度，如 160px、10rem。"},{"v":"<percentage>","d":"相对网格内容盒尺寸的百分比。"},{"v":"<track-size>+","d":"多个轨道尺寸循环用于连续的隐式列。"}],"example":".demo {\n  display: grid;\n  grid-auto-flow: column;\n  grid-auto-columns: 160px;\n}","notes":["只作用于隐式列，显式列请改 grid-template-columns。","配合 grid-auto-flow: column 时决定自动生成列的宽度。"],"syntax":"<track-size>+","initial":"auto","inherited":"否","animation":"按计算值插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-auto-columns","browser":{"chrome":"57","firefox":"70","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-auto-columns","order":345},{"name":"grid-auto-flow","js":"gridAutoFlow","zh":"自动放置规则","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"控制网格项自动填充的流向与密排方式","description":"决定未显式定位的网格项如何被自动放入网格：row 按行填满再换行，column 按列填满再换列。加上 dense 后启用密排算法，会回头填补前面留下的空洞，让布局更紧凑，但可能改变视觉顺序与阅读顺序。它是解决自动布局出现空缺问题的关键属性，配合 grid-auto-rows 或 grid-auto-columns 使用。","aliases":["自动流","grid-auto-flow","放置规则","密排"],"keywords":["网格","自动布局","密排","流向"],"values":[{"v":"row","d":"初始值，按行依次填满，行满后换下一行。"},{"v":"column","d":"按列依次填满，列满后换下一列。"},{"v":"row dense","d":"按行填充并回填空洞，布局更紧凑。"},{"v":"column dense","d":"按列填充并回填空洞。"}],"example":".demo {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  grid-auto-flow: dense;\n}","notes":["dense 会打乱视觉顺序，可能影响阅读与 Tab 顺序。","column 方向需要配合 grid-auto-columns 才有合理宽度。"],"syntax":"[ row | column ] || dense","initial":"row","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-auto-flow","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-auto-flow","order":346},{"name":"grid-auto-rows","js":"gridAutoRows","zh":"自动行尺寸","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置隐式生成的网格行轨道高度","description":"当网格项超出显式模板行时浏览器会自动创建隐式行，本属性决定这些行的高度。可用固定长度、百分比、min-content、max-content 或 minmax()，多个值循环使用。卡片流布局常写 grid-auto-rows: minmax(120px, auto)，既保证最小行高又能容纳更高的内容。","aliases":["自动行高","grid-auto-rows","隐式行尺寸"],"keywords":["网格","隐式轨道","行高","自动布局"],"values":[{"v":"auto","d":"初始值，由内容自动决定行高。"},{"v":"<length>","d":"固定行高，如 120px。"},{"v":"<percentage>","d":"相对网格内容盒尺寸的百分比。"},{"v":"minmax(<min>, <max>)","d":"限定行高范围，如 minmax(120px, auto)。"}],"example":".demo {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  grid-auto-rows: minmax(120px, auto);\n}","notes":["只作用于隐式行，显式行由 grid-template-rows 定义。","minmax() 兼顾最小高度与内容自适应，是卡片流常用写法。"],"syntax":"<track-size>+","initial":"auto","inherited":"否","animation":"按计算值插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-auto-rows","browser":{"chrome":"57","firefox":"70","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-auto-rows","order":347},{"name":"grid-column","js":"gridColumn","zh":"网格列范围","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"简写指定网格项占用的列起止线","description":"grid-column-start 与 grid-column-end 的简写，用斜杠分隔起止值，如 grid-column: 2 / 4 表示从第 2 条列线跨到第 4 条，占据两列。也可写 span 2 表示跨越两列。只写一个值时结束线为 auto，项目只占一列。列线从 1 开始计数，负数从末尾反向计数。","aliases":["列范围","grid-column","跨列"],"keywords":["网格","简写","跨列","定位"],"values":[{"v":"<start> / <end>","d":"起止列线，如 2 / 4。"},{"v":"<start>","d":"只写起始线，结束线为 auto，仅占一列。"},{"v":"span <integer>","d":"相对跨度，如 span 2 表示跨两列。"},{"v":"<custom-ident>","d":"使用模板中定义的列线名称。"}],"example":".demo {\n  grid-column: 2 / 4;\n}","notes":["列线从 1 开始，-1 表示最后一条线。","用 span 更易读：grid-column: span 2 表示跨两列。"],"syntax":"<grid-line> [ / <grid-line> ]?","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-column","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"grid-column","order":348},{"name":"grid-column-end","js":"gridColumnEnd","zh":"列结束线","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"指定网格项结束处的列线位置","description":"单独设置网格项横向的结束位置，取值为列线编号、由模板方括号定义的自定义线名，或 span N 表示相对跨度。初始值 auto 表示自动推断，通常由 grid-column-start 与项目跨度决定。它与 grid-column-start 一起构成 grid-column 简写，配合 span 使用时无需关心容器总列数。","aliases":["列结束线","grid-column-end","列结束位置"],"keywords":["网格","列线","定位","跨度"],"values":[{"v":"auto","d":"初始值，由起始线与跨度自动推断。"},{"v":"<integer>","d":"列线编号，从 1 开始，负数从末尾计数。"},{"v":"span <integer>","d":"跨越多列，如 span 2。"},{"v":"<custom-ident>","d":"引用模板中命名的列线。"}],"example":".demo {\n  grid-column-end: span 2;\n}","notes":["auto 表示交给自动放置算法决定结束位置。","推荐用 span 语法，避免写死列线编号。"],"syntax":"<grid-line>","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-column-end","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-column-end","order":349},{"name":"grid-column-start","js":"gridColumnStart","zh":"列起始线","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"指定网格项开始处的列线位置","description":"单独设置网格项横向的起始位置，可取列线编号（从 1 开始，负数自末尾计数）、由 grid-template-columns 方括号定义的自定义线名，或 span N 表示从自动位置向前跨越。初始值 auto 表示由自动放置算法决定。它是 grid-column 简写的第一个值，与 grid-column-end 配合决定占用的列范围。","aliases":["列起始线","grid-column-start","列开始位置"],"keywords":["网格","列线","定位","跨度"],"values":[{"v":"auto","d":"初始值，由自动放置算法决定起始位置。"},{"v":"<integer>","d":"列线编号，如 1 表示第一条列线。"},{"v":"<custom-ident>","d":"模板中由方括号命名的列线，如 [col-start]。"},{"v":"span <integer>","d":"从自动位置向前跨越若干列。"}],"example":".demo {\n  grid-column-start: 1;\n  grid-column-end: 3;\n}","notes":["线名写在 grid-template-columns 的方括号里，如 [col-start] 1fr。","可用负数反向计数，-1 表示最末一条线。"],"syntax":"<grid-line>","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-column-start","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-column-start","order":351},{"name":"grid-row","js":"gridRow","zh":"网格行范围","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"简写指定网格项占用的行起止线","description":"grid-row-start 与 grid-row-end 的简写，如 grid-row: 1 / 3 表示从第 1 条行线跨到第 3 条，占据两行；也可写 span 2 表示跨两行。只写一个值时结束线为 auto，项目仅占一行。常见于让侧栏、卡片在看板或仪表盘网格中纵向合并多行，形成错落的瀑布式结构。","aliases":["行范围","grid-row","跨行"],"keywords":["网格","简写","跨行","定位"],"values":[{"v":"<start> / <end>","d":"起止行线，如 1 / 3。"},{"v":"<start>","d":"只写起始线，结束线为 auto，仅占一行。"},{"v":"span <integer>","d":"相对跨度，如 span 2 表示跨两行。"},{"v":"<custom-ident>","d":"使用模板中定义的行线名称。"}],"example":".demo {\n  grid-row: 1 / 3;\n}","notes":["行线从 1 开始，负值从末尾反向计数。","只写一个起始值时结束线为 auto，项目仅占一行。"],"syntax":"<grid-line> [ / <grid-line> ]?","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-row","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"grid-row","order":353},{"name":"grid-row-end","js":"gridRowEnd","zh":"行结束线","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"指定网格项结束处的行线位置","description":"单独设置网格项纵向的结束位置，取值可为行线编号、模板中定义的自定义线名或 span N。初始值 auto 表示自动推断，常与 grid-row-start 配合决定纵向跨度。二者共同构成 grid-row 简写；如果起始行固定而结束用 span，后续添加内容行时无需修改这条声明。","aliases":["行结束线","grid-row-end","行结束位置"],"keywords":["网格","行线","定位","跨度"],"values":[{"v":"auto","d":"初始值，由起始线与跨度自动推断。"},{"v":"<integer>","d":"行线编号，从 1 开始，负数从末尾计数。"},{"v":"span <integer>","d":"跨越若干行，如 span 2。"},{"v":"<custom-ident>","d":"引用模板中命名的行线。"}],"example":".demo {\n  grid-row-end: 3;\n}","notes":["可与 grid-row-start 搭配，也可单独使用。","用 span 表示相对跨度，比绝对行线更稳健。"],"syntax":"<grid-line>","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-row-end","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-row-end","order":354},{"name":"grid-row-start","js":"gridRowStart","zh":"行起始线","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"指定网格项开始处的行线位置","description":"单独设置网格项纵向的起始位置，可取行线编号（从 1 开始）、grid-template-rows 方括号定义的自定义线名，或 span N 表示从自动位置向前跨越。初始值 auto 表示交给自动放置算法。它与 grid-row-end 组成 grid-row 简写，是构建纵向跨行布局、固定表头或侧栏的基础。","aliases":["行起始线","grid-row-start","行开始位置"],"keywords":["网格","行线","定位","跨度"],"values":[{"v":"auto","d":"初始值，由自动放置算法决定。"},{"v":"<integer>","d":"行线编号，如 2 表示第二条行线。"},{"v":"<custom-ident>","d":"模板中命名的行线。"},{"v":"span <integer>","d":"从自动位置向前跨越若干行。"}],"example":".demo {\n  grid-row-start: 2;\n  grid-row-end: 4;\n}","notes":["行线从 1 开始编号，负数从末尾计数。","同时设置 grid-area 会覆盖本属性的效果。"],"syntax":"<grid-line>","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器内的网格项目与盒","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-row-start","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-row-start","order":356},{"name":"grid-template","js":"gridTemplate","zh":"网格模板简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"简写定义网格行列模板与命名区域","description":"grid-template-rows、grid-template-columns 与 grid-template-areas 的简写。用斜杠分隔行列，如 grid-template: 60px 1fr / 200px 1fr；也可用字符串行定义命名区域。相比 grid 简写，它只涉及模板，不会重置自动流与间距，改写模板时更安全。","aliases":["网格模板","grid-template","模板简写"],"keywords":["网格","简写","模板","区域"],"values":[{"v":"<rows> / <columns>","d":"行模板在前、列模板在后，如 60px 1fr / 200px 1fr。"},{"v":"<string>+ / <columns>","d":"用字符串定义命名区域，如 \"head head\" \"side main\"。"},{"v":"none","d":"初始值，清空模板，项目进入隐式轨道。"}],"example":".demo {\n  display: grid;\n  grid-template: 60px 1fr / 200px 1fr;\n}","notes":["行在前列在后，与 grid-template-areas 的字符串行写法含义不同。","它不涉及 gap 与自动流设置，比 grid 简写更安全。"],"syntax":"none | [ <'grid-template-rows'> / <'grid-template-columns'> ] | [ <line-names>? <string> <track-size>? <line-names>? ]+ [ / <explicit-track-list> ]?","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"网格容器","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-template","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画","简写"],"id":"grid-template","order":357},{"name":"grid-template-areas","js":"gridTemplateAreas","zh":"命名网格区域","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"用字符串网格定义具名的布局区域","description":"用多行字符串画出布局草图，每个词是一个区域名，同名的连续单元格会合并成矩形区域，点号表示留空单元格。画好后子项用 grid-area: header 直接落到对应区域，让布局代码与视觉结构一一对应，改版时只改字符串即可。注意同名区域必须构成矩形，且每行字符串的单元格数要一致。","aliases":["命名区域","grid-template-areas","区域模板"],"keywords":["网格","区域","命名","模板"],"values":[{"v":"none","d":"初始值，不定义命名区域。"},{"v":"<string>+","d":"多行字符串，每个词为区域名，如 \"head head\" \"side main\"。"},{"v":".","d":"点号表示该单元格留空，不分配给任何区域。"},{"v":"...","d":"连续点号同样表示空白，用于对齐列数。"}],"example":".demo {\n  display: grid;\n  grid-template-areas: \"head head\" \"side main\";\n}","notes":["同名区域必须构成矩形，否则整条声明失效。","每一行字符串的单元格数量必须完全相同。","点号用于留空单元格，不代表名为 . 的区域。"],"syntax":"none | <string>+","initial":"none","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"网格容器","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-template-areas","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-template-areas","order":358},{"name":"grid-template-columns","js":"gridTemplateColumns","zh":"网格列模板","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"定义网格容器显式列轨道的尺寸","description":"用轨道列表定义显式列的宽度：固定长度、百分比、fr 弹性份数、auto、min-content、max-content 以及 repeat()、minmax()。repeat(auto-fill, minmax(200px, 1fr)) 是最常用的自适应卡片写法。方括号可为网格线命名；超出范围的项目进入由 grid-auto-columns 控制的隐式列。","aliases":["列模板","grid-template-columns","列轨道","列定义"],"keywords":["网格","列宽","模板","响应式"],"values":[{"v":"none","d":"初始值，不定义显式列，项目全部进入隐式列。"},{"v":"<length>","d":"固定列宽，如 200px、12rem。"},{"v":"<flex>","d":"fr 弹性份数，如 1fr、2fr，按比例分配剩余宽度。"},{"v":"minmax(<min>, <max>)","d":"列宽范围，如 minmax(200px, 1fr)。"},{"v":"repeat(<count>, <track>)","d":"重复轨道，计数可用 auto-fill 或 auto-fit。"},{"v":"subgrid","d":"继承父网格的列轨道，较新特性。"}],"example":".demo {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));\n}","notes":["auto-fit 会折叠空轨道并让项目撑满，auto-fill 保留空轨道。","隐式列宽度由 grid-auto-columns 控制。"],"syntax":"none | <track-list> | <auto-track-list> | subgrid <line-name-list>?","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色列表插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-template-columns","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-template-columns","order":359},{"name":"grid-template-rows","js":"gridTemplateRows","zh":"网格行模板","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"定义网格容器显式行轨道的尺寸","description":"用轨道列表定义显式行的高度，支持固定长度、百分比、fr、auto、min-content、max-content 及 repeat()、minmax()。行高常写成 minmax(120px, auto)，让内容多的行自动增高；也可用 subgrid 继承父网格的行轨道。超出显式行的项目进入隐式行，其高度由 grid-auto-rows 决定。","aliases":["行模板","grid-template-rows","行轨道","行定义"],"keywords":["网格","行高","模板","布局"],"values":[{"v":"none","d":"初始值，不定义显式行。"},{"v":"<length>","d":"固定行高，如 80px。"},{"v":"<flex>","d":"fr 份数，如 1fr，按比例分配剩余高度。"},{"v":"minmax(<min>, <max>)","d":"行高范围，如 minmax(120px, auto)。"},{"v":"repeat(<count>, <track>)","d":"重复轨道定义。"},{"v":"subgrid","d":"继承父网格的行轨道，较新特性。"}],"example":".demo {\n  display: grid;\n  grid-template-rows: auto 1fr auto;\n}","notes":["超出显式行的项目会进入隐式行，高度由 grid-auto-rows 控制。","subgrid 支持范围较新，使用前确认目标浏览器。"],"syntax":"none | <track-list> | <auto-track-list> | subgrid <line-name-list>?","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色列表插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-template-rows","browser":{"chrome":"57","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"grid-template-rows","order":360},{"name":"justify-content","js":"justifyContent","zh":"主轴内容分配","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"在主轴方向上分配项目的对齐与间距","description":"沿主轴对齐弹性项目，或在网格中分配列方向剩余空间：center 居中、flex-start/flex-end 靠边、space-between/around/evenly 按不同规则分散、stretch 拉伸轨道。弹性容器中项目总宽小于容器时最常用。内容溢出时建议使用 safe 等安全对齐关键字，否则起始项可能被裁到不可滚动区域。","aliases":["主轴对齐","justify-content","内容分布","水平对齐"],"keywords":["对齐","弹性","网格","分布"],"values":[{"v":"normal","d":"初始值，多数场景等同 flex-start 或 stretch。"},{"v":"flex-start / flex-end","d":"靠主轴起始或结束侧对齐。"},{"v":"center","d":"整体居中，剩余空间均分到两侧。"},{"v":"space-between","d":"首尾贴边，空间均匀分布在项目之间。"},{"v":"space-around","d":"每个项目两侧留等量空间，项目之间是两端的两倍。"},{"v":"space-evenly","d":"所有间隙完全相等。"},{"v":"stretch","d":"拉伸自动尺寸的轨道或项目以填满主轴。"}],"example":".demo {\n  display: flex;\n  justify-content: space-between;\n}","notes":["弹性容器中它分配主轴空间，交叉轴对齐用 align-items。","内容溢出时用 safe 前缀可避免首项被裁掉。"],"syntax":"normal | <content-distribution> | <overflow-position>? [ <content-position> | left | right ]","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"弹性容器","computed":"按指定值","specGroups":["CSS Box Alignment","CSS Flexible Box Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/justify-content","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"justify-content","order":386},{"name":"justify-items","js":"justifyItems","zh":"项目行内对齐","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置项目在行内轴上的默认对齐方式","description":"为网格容器或块级容器内的项目设置行内轴（通常为水平方向）的默认对齐，决定项目在自身轨道或区域内如何摆放：stretch 撑满、center 居中、start/end 靠边，left/right 为物理方向关键字。它是容器属性，单个项目可用 justify-self 覆盖。注意它对弹性项目无效，弹性主轴对齐要用 justify-content。","aliases":["行内对齐","justify-items","项目水平对齐"],"keywords":["对齐","网格","行内轴","容器属性"],"values":[{"v":"normal","d":"行为与 stretch 类似，在网格中让项目撑满区域。"},{"v":"legacy","d":"初始值，沿用旧版对齐行为，多等同于 normal。"},{"v":"stretch","d":"项目拉伸填满所在区域。"},{"v":"center","d":"在行内轴上居中。"},{"v":"start / end","d":"靠行内轴起始或结束侧对齐。"},{"v":"left / right","d":"物理方向对齐，不受书写模式影响。"}],"example":".demo {\n  display: grid;\n  justify-items: center;\n}","notes":["对弹性项目无效，弹性主轴对齐请用 justify-content。","初始值为 legacy，表示沿用旧版对齐行为。"],"syntax":"normal | stretch | <baseline-position> | <overflow-position>? [ <self-position> | left | right ] | legacy | legacy && [ left | right | center ] | anchor-center","initial":"legacy","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"按指定值","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/justify-items","browser":{"chrome":"52","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"justify-items","order":387},{"name":"justify-self","js":"justifySelf","zh":"单项行内对齐","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"单独覆盖项目在行内轴上的对齐","description":"作用于网格项、块级盒子与绝对定位盒子，单独覆盖父容器 justify-items 的行内轴对齐方式。auto 表示继承容器设置；stretch 撑满所在轨道；start/end/center 决定项目在轨道内的水平位置。常用来让某个网格项单独居中或靠右而不影响其他项目，对弹性项目不生效。","aliases":["单项对齐","justify-self","行内对齐覆盖"],"keywords":["对齐","网格","覆盖","行内轴"],"values":[{"v":"auto","d":"初始值，继承父容器的 justify-items 值。"},{"v":"normal","d":"在网格中通常表现为 stretch。"},{"v":"stretch","d":"拉伸填满所在轨道。"},{"v":"center","d":"在行内轴上居中。"},{"v":"start / end","d":"靠行内轴起始或结束侧对齐。"},{"v":"left / right","d":"物理方向对齐。"}],"example":".demo {\n  justify-self: center;\n}","notes":["对弹性项目无效，弹性项目可用 margin: auto 实现类似效果。","auto 表示继承而不是取消对齐。"],"syntax":"auto | normal | stretch | <baseline-position> | <overflow-position>? [ <self-position> | left | right ] | anchor-center","initial":"auto","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级盒、绝对定位盒与网格项目","computed":"按指定值","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/justify-self","browser":{"chrome":"57","firefox":"45","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"justify-self","order":388},{"name":"order","js":"order","zh":"排序权重","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"调整项目在布局中的显示先后顺序","description":"通过整数权重改变弹性或网格项目的视觉顺序，初始值 0，数值小的排在前面，可正可负。它只改变视觉顺序，DOM 顺序与 Tab 焦点顺序保持不变，过度使用会造成视觉顺序与键盘顺序不一致的无障碍问题。若要让阅读顺序跟随视觉顺序，可配合 reading-flow 与 reading-order。","aliases":["排序","order","顺序","权重"],"keywords":["弹性","网格","顺序","无障碍"],"values":[{"v":"0","d":"初始值，按源顺序排列。"},{"v":"<integer>","d":"任意整数，值小者在前，负值可把项目提前。"}],"example":".demo {\n  order: -1;\n}","notes":["只改视觉顺序，不改变 DOM 与焦点顺序，注意无障碍影响。","仅对弹性项目、网格项目及绝对定位子元素有效。"],"syntax":"<integer>","initial":"0","inherited":"否","animation":"整数插值","percentages":"不适用","appliesTo":"弹性项目、网格项目与绝对定位容器的子元素","computed":"按指定值","specGroups":["CSS Display"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/order","browser":{"chrome":"29","firefox":"20","safari":"9","edge":"12"},"tier":"core","tags":["可动画"],"id":"order","order":459},{"name":"place-content","js":"placeContent","zh":"内容双向对齐简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置两个方向的内容对齐","description":"align-content 与 justify-content 的简写，写一个值时两者相同，写两个值时依次为块向、行向。最典型的用法是 place-content: center 让网格或弹性内容整体居中。它只在多行弹性或多轨道网格中有完整意义，单行弹性容器里 align-content 那一部分不起作用。","aliases":["双向对齐简写","place-content","内容对齐简写"],"keywords":["对齐","简写","网格","弹性"],"values":[{"v":"<'align-content'>","d":"一个值时同时作为 align-content 与 justify-content。"},{"v":"<'align-content'> <'justify-content'>","d":"两个值时依次为块向与行向，如 space-between center。"},{"v":"center","d":"最常用，内容在两个方向都居中。"}],"example":".demo {\n  display: grid;\n  place-content: center;\n  min-height: 200px;\n}","notes":["两个值的顺序是 align-content 在前、justify-content 在后。","单行弹性容器中 align-content 部分无效。"],"syntax":"<'align-content'> <'justify-content'>?","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"多行弹性容器","computed":"由各长写属性决定","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/place-content","browser":{"chrome":"59","firefox":"45","safari":"9","edge":"79"},"tier":"core","tags":["可动画","简写"],"id":"place-content","order":500},{"name":"place-items","js":"placeItems","zh":"项目双向对齐简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置项目的两个方向对齐","description":"align-items 与 justify-items 的简写，一个值时两者一致，两个值时依次为块向、行向。网格布局中 place-items: center 是最常用的单行居中写法，让所有项目在自己的单元格里水平垂直都居中。它作用于容器，单个项目要单独覆盖时使用 place-self。","aliases":["双向项目对齐","place-items","项目对齐简写"],"keywords":["对齐","简写","网格","居中"],"values":[{"v":"<'align-items'>","d":"一个值时同时应用于两个方向。"},{"v":"<'align-items'> <'justify-items'>","d":"两个值依次为块向与行向，如 center start。"},{"v":"center","d":"最常用，让项目在单元格内双向居中。"}],"example":".demo {\n  display: grid;\n  place-items: center;\n  min-height: 200px;\n}","notes":["网格整体居中常用 place-items: center 一条声明完成。","弹性布局中只有 align-items 部分生效。"],"syntax":"<'align-items'> <'justify-items'>?","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"所有元素","computed":"由各长写属性决定","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/place-items","browser":{"chrome":"59","firefox":"45","safari":"11","edge":"79"},"tier":"core","tags":["可动画","简写"],"id":"place-items","order":501},{"name":"place-self","js":"placeSelf","zh":"单项双向对齐简写","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"同时设置 align-self 与 justify-self","description":"align-self 与 justify-self 的简写，用于单个项目设置两个方向的对齐：一个值时两者相同，两个值时依次为块向、行向。网格项用 place-self: center 可在自己的区域内双向居中，无需依赖父容器的 place-items。对弹性项目只有块向对齐部分生效，行内方向需借助 margin: auto。","aliases":["双向单项对齐","place-self","单项对齐简写"],"keywords":["对齐","简写","网格","覆盖"],"values":[{"v":"<'align-self'>","d":"一个值时同时作为两个方向的对齐值。"},{"v":"<'align-self'> <'justify-self'>","d":"两个值依次为块向与行向，如 center end。"},{"v":"center","d":"在所在区域内双向居中。"}],"example":".demo {\n  place-self: center;\n}","notes":["两个值顺序为 align-self 在前、justify-self 在后。","弹性项目中仅块向对齐生效。"],"syntax":"<'align-self'> <'justify-self'>?","initial":"由各长写属性决定","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块级盒、绝对定位盒与网格项目","computed":"由各长写属性决定","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/place-self","browser":{"chrome":"59","firefox":"45","safari":"11","edge":"79"},"tier":"core","tags":["可动画","简写"],"id":"place-self","order":502},{"name":"row-gap","js":"rowGap","zh":"行间距","category":"flexgrid","categoryName":"弹性与网格","status":"standard","statusLabel":"标准","summary":"设置行与行之间的空隙间距","description":"定义行与行之间的间距，适用于网格、允许换行的弹性布局与多列布局。normal 一般计算为 0，长度值直接生效，百分比在网格中相对内容盒尺寸解析。它只在行之间产生空隙，容器首尾不会多出空白，也不会在最后一行留下多余间距，是 gap 简写的第一个值。","aliases":["行间距","row-gap","行间隔"],"keywords":["间距","网格","弹性","行"],"values":[{"v":"normal","d":"初始值，一般计算为 0（多列布局有特殊规则）。"},{"v":"<length>","d":"固定行间距，如 24px、1rem。"},{"v":"<percentage>","d":"相对网格内容盒尺寸的百分比。"}],"example":".demo {\n  display: grid;\n  row-gap: 24px;\n}","notes":["只在行之间产生间距，容器首尾不会多出空隙。","已废弃的旧名为 grid-row-gap。"],"syntax":"normal | <length-percentage>","initial":"normal","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对内容区对应尺寸","appliesTo":"多列元素、弹性容器、网格容器","computed":"按指定值（normal 除多列外计算为 0）","specGroups":["CSS Box Alignment"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/row-gap","browser":{"chrome":"47","firefox":"52","safari":"10.1","edge":"16"},"tier":"core","tags":["可动画"],"id":"row-gap","order":519},{"name":"align-tracks","js":"alignTracks","zh":"轨道块向对齐","category":"flexgrid","categoryName":"弹性与网格","status":"nonstandard","statusLabel":"非标准","summary":"为砌体布局的轨道设置块向对齐","description":"配合砌体（瀑布流）布局使用的属性，用于设置各轨道在块轴方向的对齐与分布方式，语法与 align-content 类似但分别作用于每条轨道。属于非标准、实验性特性，只有极少数实验实现支持且行为可能调整，不建议用于生产环境；需要瀑布流时优先考虑多列布局或 JS 方案。","aliases":["轨道对齐","align-tracks","砌体对齐"],"keywords":["砌体","网格","对齐","非标准"],"values":[{"v":"normal","d":"初始值，各轨道按默认行为排列。"},{"v":"start / end / center","d":"轨道在块向上靠起始、结束侧或居中。"},{"v":"space-between / space-around / space-evenly","d":"在轨道之间分配剩余空间。"}],"example":".demo {\n  display: grid;\n  grid-template-rows: masonry;\n  align-tracks: space-between;\n}","notes":["非标准特性，仅个别实验实现支持，不建议生产使用。","需配合 grid-template-rows: masonry 才有意义。"],"syntax":"[ normal | <baseline-position> | <content-distribution> | <overflow-position>? <content-position> ]#","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"块轴使用砌体布局的网格容器","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"","browser":null,"tier":"extra","tags":["可动画","非标准"],"id":"align-tracks","order":116},{"name":"grid-column-gap","js":"gridColumnGap","zh":"网格列间距","category":"flexgrid","categoryName":"弹性与网格","status":"obsolete","statusLabel":"已废弃","summary":"已废弃的网格列间距旧写法","description":"早期网格规范中设置列间距的属性，功能等同于现在的 column-gap。随着间距属性被推广到弹性与多列布局，标准统一改用 column-gap 命名，本属性随之标记为废弃。旧代码一般仍能生效，但新项目应统一使用 column-gap 或 gap，避免与后续规范脱节。","aliases":["列间距","grid-column-gap","旧列间距"],"keywords":["间距","网格","废弃","别名"],"values":[{"v":"<length-percentage>","d":"列间距，如 16px，百分比相对内容盒尺寸。"},{"v":"0","d":"初始值，无列间距。"}],"example":".demo {\n  display: grid;\n  grid-column-gap: 16px;\n}","notes":["已废弃，标准替代为 column-gap，新代码请改用 column-gap 或 gap。","它是旧 grid-gap 简写的组成部分。"],"syntax":"<length-percentage>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/column-gap","browser":null,"tier":"extra","tags":["可动画","已废弃"],"id":"grid-column-gap","order":350},{"name":"grid-gap","js":"gridGap","zh":"网格间距简写","category":"flexgrid","categoryName":"弹性与网格","status":"obsolete","statusLabel":"已废弃","summary":"已废弃的网格行列间距旧简写","description":"早期网格布局中同时设置 grid-row-gap 与 grid-column-gap 的简写，一个值表示行列相同，两个值依次为行间距、列间距。由于间距属性后来被推广到弹性与多列布局，标准改名为 gap、row-gap、column-gap，本属性因此废弃。旧项目可保留，但新代码应直接使用 gap。","aliases":["网格间距","grid-gap","旧间距简写"],"keywords":["间距","网格","废弃","简写"],"values":[{"v":"<row-gap> <column-gap>?","d":"一个值行列相同，两个值依次为行、列间距。"},{"v":"<length>","d":"常见写法，如 12px、12px 20px。"}],"example":".demo {\n  display: grid;\n  grid-gap: 12px 20px;\n}","notes":["已废弃，标准替代为 gap。","两个值的顺序是行间距在前、列间距在后。"],"syntax":"<'grid-row-gap'> <'grid-column-gap'>?","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"不适用","appliesTo":"网格容器","computed":"由各长写属性决定","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/gap","browser":null,"tier":"extra","tags":["可动画","已废弃","简写"],"id":"grid-gap","order":352},{"name":"grid-row-gap","js":"gridRowGap","zh":"网格行间距","category":"flexgrid","categoryName":"弹性与网格","status":"obsolete","statusLabel":"已废弃","summary":"已废弃的网格行间距旧写法","description":"早期网格规范中设置行间距的属性，功能等同于现在的 row-gap。随着间距属性被推广到弹性与多列布局，标准统一改用 row-gap 命名，本属性随之废弃。现存代码一般仍能生效，维护时建议一并替换为 row-gap 或 gap，让间距设置集中到通用属性上。","aliases":["行间距","grid-row-gap","旧行间距"],"keywords":["间距","网格","废弃","别名"],"values":[{"v":"<length-percentage>","d":"行间距，如 20px，百分比相对内容盒尺寸。"},{"v":"0","d":"初始值，无行间距。"}],"example":".demo {\n  display: grid;\n  grid-row-gap: 20px;\n}","notes":["已废弃，改用 row-gap 或 gap。","与 grid-column-gap 一起可由 grid-gap 简写设置。"],"syntax":"<length-percentage>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对内容区对应尺寸","appliesTo":"网格容器","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/row-gap","browser":null,"tier":"extra","tags":["可动画","已废弃"],"id":"grid-row-gap","order":355},{"name":"justify-tracks","js":"justifyTracks","zh":"轨道行向对齐","category":"flexgrid","categoryName":"弹性与网格","status":"nonstandard","statusLabel":"非标准","summary":"为砌体布局的轨道设置行向对齐","description":"砌体（瀑布流）布局相关属性，用于控制各轨道在行内方向的分布方式，可用 space-between、center、stretch 等值让轨道在剩余空间中拉开或居中。它属于非标准、实验性特性，只在个别浏览器的实验实现中存在，行为可能随规范讨论调整，生产环境应避免依赖。","aliases":["轨道行向对齐","justify-tracks","砌体轨道"],"keywords":["砌体","网格","对齐","非标准"],"values":[{"v":"normal","d":"初始值，轨道按默认方式分布。"},{"v":"center","d":"轨道在行内方向整体居中。"},{"v":"space-between / space-around / space-evenly","d":"在轨道之间分配行内剩余空间。"}],"example":".demo {\n  display: grid;\n  grid-template-columns: masonry;\n  justify-tracks: space-between;\n}","notes":["非标准特性，浏览器支持极为有限。","砌体布局标准仍在讨论，属性可能更名或移除。"],"syntax":"[ normal | <content-distribution> | <overflow-position>? [ <content-position> | left | right ] ]#","initial":"normal","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"行内轴使用砌体布局的网格容器","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"","browser":null,"tier":"extra","tags":["可动画","非标准"],"id":"justify-tracks","order":389},{"name":"masonry-auto-flow","js":"masonryAutoFlow","zh":"砌体自动排布","category":"flexgrid","categoryName":"弹性与网格","status":"nonstandard","statusLabel":"非标准","summary":"控制砌体布局中项目的填放方式","description":"砌体（瀑布流）布局中控制项目如何填入轨道：pack 为默认的紧凑填充，next 让项目按顺序推进到下一条轨道；definite-first 优先放置尺寸确定的项目，ordered 强调按文档顺序排列以保持一致。属于非标准实验特性，只有实验实现支持，不能作为生产布局方案。","aliases":["砌体排布","masonry-auto-flow","瀑布流排序"],"keywords":["砌体","网格","自动布局","非标准"],"values":[{"v":"pack","d":"初始值，按最紧凑方式把项目填入轨道。"},{"v":"next","d":"项目按顺序推进到下一条轨道，而非回填空隙。"},{"v":"definite-first / ordered","d":"优先放置尺寸确定的项目，或更强调文档顺序。"}],"example":".demo {\n  display: grid;\n  grid-template-rows: masonry;\n  masonry-auto-flow: next ordered;\n}","notes":["非标准、实验性属性，仅实验实现支持。","砌体规范未定稿，取值与语义可能变化。"],"syntax":"[ pack | next ] || [ definite-first | ordered ]","initial":"pack","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"使用砌体布局的网格容器","computed":"按指定值","specGroups":["CSS Grid Layout"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/grid-auto-flow","browser":null,"tier":"extra","tags":["可动画","非标准"],"id":"masonry-auto-flow","order":435},{"name":"aspect-ratio","js":"aspectRatio","zh":"宽高比","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"为元素指定首选的宽高比例","description":"让元素按给定比例计算尺寸，16 / 9 表示宽高比 16:9。只有当至少一个方向的尺寸为 auto 时比例才生效；宽高都固定时该属性被忽略。常配合 width: 100% 让图片、视频或卡片按比例撑高，避免加载时布局抖动。写 auto 16 / 9 表示优先使用内容自身比例，否则回退到指定比例。","aliases":["宽高比","aspect-ratio","比例","纵横比"],"keywords":["比例","尺寸","图片","布局"],"values":[{"v":"auto","d":"初始值，使用元素的内在比例，没有则不受约束。"},{"v":"<ratio>","d":"比例值，如 16 / 9、1 / 1、4 / 3。"},{"v":"auto <ratio>","d":"优先用内容固有比例，没有时用给定比例。"}],"example":".demo {\n  aspect-ratio: 16 / 9;\n  width: 100%;\n  object-fit: cover;\n}","notes":["宽高都固定时 aspect-ratio 不起作用。","auto <ratio> 用于为图片提供兜底比例。"],"syntax":"auto || <ratio>","initial":"auto","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"除行内盒及内部 Ruby / 表格盒外的所有元素","computed":"按指定值","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/aspect-ratio","browser":{"chrome":"88","firefox":"89","safari":"15","edge":"88"},"tier":"core","tags":["可动画"],"id":"aspect-ratio","order":137},{"name":"block-size","js":"blockSize","zh":"块向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置元素的块向尺寸","description":"逻辑属性，设置元素在块轴方向上的尺寸。横排书写时等价于 height，竖排时等价于 width，随 writing-mode 自动切换。取值与 height 相同，支持 auto、长度与百分比（相对包含块的块向尺寸）。由于尺寸方向与物理方向解耦，它在多语言与竖排布局中比 height 更稳妥。","aliases":["块向尺寸","block-size","逻辑高度"],"keywords":["尺寸","逻辑属性","书写模式","布局"],"values":[{"v":"auto","d":"初始值，由内容或布局规则决定。"},{"v":"<length>","d":"固定尺寸，如 320px、20rem。"},{"v":"<percentage>","d":"相对包含块块向尺寸的百分比。"},{"v":"min-content / max-content / fit-content","d":"按内容或可用空间决定尺寸。"}],"example":".demo {\n  writing-mode: horizontal-tb;\n  block-size: 320px;\n}","notes":["横排时等同 height，竖排时等同 width。","横排下同时写 height 与 block-size 时后声明者生效。"],"syntax":"<'width'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块块轴尺寸","appliesTo":"与 width / height 相同","computed":"与 width / height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/block-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"block-size","order":154},{"name":"box-sizing","js":"boxSizing","zh":"盒尺寸模型","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"决定宽高是否包含内边距与边框","description":"content-box 为初始值，width 只计算内容区，padding 与 border 会额外增加实际占位，容易导致布局超宽；border-box 让 width 包含 padding 与 border，设定值就是元素实际宽度。多数项目在全局重置时统一设为 border-box，它影响宽高及 min/max 尺寸的解析方式。","aliases":["盒模型","box-sizing","边框盒","尺寸模型"],"keywords":["盒模型","尺寸","边框","布局"],"values":[{"v":"content-box","d":"初始值，宽高只算内容区，不含内边距与边框。"},{"v":"border-box","d":"宽高包含内边距与边框，布局尺寸更好预测。"}],"example":".demo {\n  box-sizing: border-box;\n  width: 100%;\n  padding: 16px;\n}","notes":["border-box 下元素总宽等于设定的 width，布局更可控。","全站切换 box-sizing 会改变既有尺寸计算结果，需整体统一。"],"syntax":"content-box | border-box","initial":"content-box","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"接受 width / height 的所有元素","computed":"按指定值","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-sizing","browser":{"chrome":"10","firefox":"29","safari":"5.1","edge":"12"},"tier":"core","tags":["可动画"],"id":"box-sizing","order":228},{"name":"contain-intrinsic-block-size","js":"containIntrinsicBlockSize","zh":"占位块向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"为尺寸包含元素指定块向的占位尺寸","description":"当元素因 contain: size 或 content-visibility 导致尺寸不再由内容决定时，用它提供块向的占位尺寸，避免布局塌缩或滚动条位置跳动。它是 contain-intrinsic-size 在块向的逻辑方向长写，横排时相当于设置占位高度。auto 前缀表示浏览器记住元素上次渲染的实际尺寸，首次仍使用给定值。","aliases":["占位块向尺寸","contain-intrinsic-block-size","占位高度"],"keywords":["包含","占位","性能","尺寸"],"values":[{"v":"none","d":"初始值，不使用内部占位尺寸。"},{"v":"<length>","d":"占位块向尺寸，如 400px。"},{"v":"auto <length>","d":"优先记住上次渲染尺寸，无记录时使用给定长度。"}],"example":".demo {\n  content-visibility: auto;\n  contain-intrinsic-block-size: 400px;\n}","notes":["auto 前缀让浏览器在第二次渲染后采用真实尺寸，更贴近实际。","它是 contain-intrinsic-size 的逻辑方向长写。"],"syntax":"auto? [ none | <length> ]","initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"可应用尺寸包含的元素","computed":"按指定值，长度值已计算","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain-intrinsic-block-size","browser":{"chrome":"95","firefox":"107","safari":"17","edge":"95"},"tier":"core","tags":["可动画"],"id":"contain-intrinsic-block-size","order":257},{"name":"contain-intrinsic-height","js":"containIntrinsicHeight","zh":"占位高度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"为尺寸包含元素指定占位高度","description":"当元素因 contain: size 或 content-visibility 导致高度不再由内容决定时，用它提供占位高度，避免内容渲染前后高度突变、滚动条位置跳动。属于 contain-intrinsic-size 简写中的高度部分，是物理方向版本；auto 前缀表示浏览器记住上次渲染的实际高度，首次仍使用给定值。横向滚动列表里也常用来预留高度。","aliases":["占位高度","contain-intrinsic-height","内部固有高度"],"keywords":["包含","占位","性能","高度"],"values":[{"v":"none","d":"初始值，不使用占位高度。"},{"v":"<length>","d":"固定占位高度，如 200px。"},{"v":"auto <length>","d":"优先使用上次渲染记住的高度，没有记录时用给定长度。"}],"example":".demo {\n  content-visibility: auto;\n  contain-intrinsic-height: 200px;\n}","notes":["auto 前缀要等元素渲染过一次后才会生效。","常与 contain-intrinsic-width 一起使用，或直接写 contain-intrinsic-size 简写。"],"syntax":"auto? [ none | <length> ]","initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"可应用尺寸包含的元素","computed":"按指定值，长度值已计算","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain-intrinsic-height","browser":{"chrome":"95","firefox":"107","safari":"17","edge":"95"},"tier":"core","tags":["可动画"],"id":"contain-intrinsic-height","order":258},{"name":"contain-intrinsic-inline-size","js":"containIntrinsicInlineSize","zh":"占位行内尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"为尺寸包含元素指定行向占位尺寸","description":"逻辑方向版本，为尺寸包含元素提供行内轴的占位尺寸：横排时相当于占位宽度，竖排时相当于占位高度，随 writing-mode 自动切换。它属于 contain-intrinsic-size 简写族，用于 contain: size 或 content-visibility 下避免元素宽度塌缩成 0。auto 前缀表示沿用上次渲染记住的尺寸。","aliases":["占位行内尺寸","contain-intrinsic-inline-size","逻辑占位宽"],"keywords":["包含","占位","逻辑属性","尺寸"],"values":[{"v":"none","d":"初始值，不使用占位行内尺寸。"},{"v":"<length>","d":"占位长度，如 120px。"},{"v":"auto <length>","d":"优先使用上次渲染记住的尺寸，否则用给定长度。"}],"example":".demo {\n  contain: size;\n  contain-intrinsic-inline-size: 120px;\n}","notes":["横排时等同 contain-intrinsic-width，竖排时等同 contain-intrinsic-height。","只有元素受到尺寸包含影响时才需要它。"],"syntax":"auto? [ none | <length> ]","initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"可应用尺寸包含的元素","computed":"按指定值，长度值已计算","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain-intrinsic-inline-size","browser":{"chrome":"95","firefox":"107","safari":"17","edge":"95"},"tier":"core","tags":["可动画"],"id":"contain-intrinsic-inline-size","order":259},{"name":"contain-intrinsic-size","js":"containIntrinsicSize","zh":"占位尺寸简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"同时指定尺寸包含元素的占位宽高","description":"contain-intrinsic-width 与 contain-intrinsic-height 的简写，为尺寸包含元素提供占位宽高：一个值时宽高相同，两个值时依次为宽、高。它是 content-visibility: auto 的常用搭档，让视口外元素仍占合理空间，滚动条不会跳动。auto 前缀表示先采用上次渲染记住的真实尺寸。","aliases":["占位尺寸","contain-intrinsic-size","固有尺寸占位"],"keywords":["包含","占位","性能","简写"],"values":[{"v":"none","d":"初始值，不提供占位尺寸。"},{"v":"<length>","d":"宽高相同的占位尺寸，如 500px。"},{"v":"<width> <height>","d":"依次为占位宽、占位高，如 600px 400px。"},{"v":"auto <length>","d":"记住上次渲染尺寸，首次使用给定长度。"}],"example":".demo {\n  content-visibility: auto;\n  contain-intrinsic-size: 600px 400px;\n}","notes":["不写占位尺寸时，视口外元素高度按 0 计算，滚动条会跳。","简写的实现早于部分长写属性，兼容旧版时优先用简写。"],"syntax":"[ auto? [ none | <length> ] ]{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"各长写属性分别插值","percentages":"各长写属性分别计算","appliesTo":"可应用尺寸包含的元素","computed":"由各长写属性决定","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain-intrinsic-size","browser":{"chrome":"83","firefox":"107","safari":"17","edge":"83"},"tier":"core","tags":["可动画","简写"],"id":"contain-intrinsic-size","order":260},{"name":"contain-intrinsic-width","js":"containIntrinsicWidth","zh":"占位宽度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"为尺寸包含元素指定占位宽度","description":"为受尺寸包含影响的元素提供占位宽度。它最常用在横向滚动的卡片列表中：配合 content-visibility 或 contain: size，让尚未渲染的卡片仍占据合理宽度，避免列表长度突变。作为 contain-intrinsic-size 简写的宽度部分，auto 前缀表示记住上次渲染的真实宽度。","aliases":["占位宽度","contain-intrinsic-width","内部固有宽度"],"keywords":["包含","占位","性能","宽度"],"values":[{"v":"none","d":"初始值，不使用占位宽度。"},{"v":"<length>","d":"固定占位宽度，如 160px。"},{"v":"auto <length>","d":"优先使用记住的渲染宽度，否则用给定长度。"}],"example":".demo {\n  contain: size;\n  contain-intrinsic-width: 160px;\n}","notes":["与 contain-intrinsic-height 一起构成 contain-intrinsic-size 简写。","仅在元素尺寸受包含性影响时才会被使用。"],"syntax":"auto? [ none | <length> ]","initial":"none","inherited":"否","animation":"按计算值插值","percentages":"不适用","appliesTo":"可应用尺寸包含的元素","computed":"按指定值，长度值已计算","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/contain-intrinsic-width","browser":{"chrome":"95","firefox":"107","safari":"17","edge":"95"},"tier":"core","tags":["可动画"],"id":"contain-intrinsic-width","order":261},{"name":"height","js":"height","zh":"高度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素内容盒的高度","description":"指定元素在块向上的实际高度，初始值 auto 表示由内容撑开。百分比需要父级有确定高度才能解析，父级高度为 auto 时百分比常等同于 auto。高度受 min-height、max-height 约束，若同时设置了宽高，aspect-ratio 会被忽略。对非替换的行内元素无效，此时高度由行高与字体决定。","aliases":["高度","height","元素高度","定高"],"keywords":["尺寸","高度","盒模型","布局"],"values":[{"v":"auto","d":"初始值，高度由内容与布局规则决定。"},{"v":"<length>","d":"固定高度，如 320px、20rem。"},{"v":"<percentage>","d":"相对父元素高度的百分比，需要父级高度确定。"},{"v":"min-content / max-content / fit-content","d":"按内容的固有高度决定。"},{"v":"<anchor-size()>","d":"锚点定位下取锚点的尺寸，较新特性。"}],"example":".demo {\n  height: 320px;\n  overflow: auto;\n}","notes":["百分比高度要生效，父级必须有可确定的 height。","min-height 与 max-height 会覆盖 height 的最终结果。"],"syntax":"auto | <length-percentage [0,∞]> | min-content | max-content | fit-content | fit-content(<length-percentage [0,∞]>) | <calc-size()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块（生成盒的包含块）","appliesTo":"除不可替换元素与表格列外的元素","computed":"百分比、auto 或绝对长度","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/height","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"height","order":362},{"name":"inline-size","js":"inlineSize","zh":"行向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置元素的行向尺寸","description":"逻辑属性，设置元素在行内轴方向上的尺寸。横排书写时等价于 width，竖排时等价于 height，随 writing-mode 自动切换。取值与 width 相同，支持 auto、长度与百分比（相对包含块的行向尺寸）。在多语言与竖排布局中用它替代 width，可让尺寸方向自动适配书写模式。","aliases":["行向尺寸","inline-size","逻辑宽度"],"keywords":["尺寸","逻辑属性","书写模式","布局"],"values":[{"v":"auto","d":"初始值，由内容或布局规则决定。"},{"v":"<length>","d":"固定尺寸，如 240px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"},{"v":"min-content / max-content / fit-content","d":"按内容与可用空间决定。"}],"example":".demo {\n  inline-size: 240px;\n}","notes":["横排时等同 width，竖排时等同 height。","与 width 同时声明时，后写入者生效。"],"syntax":"<'width'>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块行内轴尺寸","appliesTo":"与 width / height 相同","computed":"与 width / height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/inline-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"inline-size","order":372},{"name":"margin","js":"margin","zh":"外边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"一次性设置四个方向的外边距","description":"margin-top、margin-right、margin-bottom、margin-left 的简写，取值遵循顺时针上右下左规则：1 个值四边相同，2 个值上下与左右，3 个值为上、左右、下，4 个值为上右下左。它可以取负值，auto 在水平方向可实现块级元素居中或弹性布局的剩余空间分配。相邻块级元素的垂直外边距会合并。","aliases":["外边距","margin","边距","外边距简写"],"keywords":["外边距","简写","盒模型","居中"],"values":[{"v":"<length>{1,4}","d":"1 至 4 个长度值，按上右下左分配，可为负。"},{"v":"<percentage>{1,4}","d":"百分比，四边都相对包含块的行向尺寸（宽度）解析。"},{"v":"auto","d":"由浏览器分配剩余空间，常用于水平居中。"},{"v":"0 auto","d":"上下为 0、左右自动，块级居中常用写法。"}],"example":".demo {\n  margin: 0 auto;\n  max-width: 960px;\n}","notes":["相邻块级上下外边距会合并，取较大者而非相加。","百分比外边距四边都以包含块宽度为基准，纵向也是。"],"syntax":"<'margin-top'>{1,4}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除表格显示类型外的所有元素","computed":"由各长写属性决定","specGroups":["CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画","简写"],"id":"margin","order":402},{"name":"margin-block","js":"marginBlock","zh":"块向外边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"同时设置块向起始与结束的外边距","description":"margin-block-start 与 margin-block-end 的简写，按书写模式映射到上下（横排）或左右（竖排）。1 个值表示两端相同，2 个值依次为起始、结束。多语言页面里用它替代 margin-top/margin-bottom 可随书写方向自动调整，但它同样参与垂直外边距合并。","aliases":["块向外边距","margin-block","逻辑上下边距"],"keywords":["外边距","逻辑属性","简写","书写模式"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个长度值，对应块向两端，可为负。"},{"v":"<percentage>{1,2}","d":"百分比仍相对包含块的行向尺寸解析。"},{"v":"auto","d":"两端均为自动，由布局规则分配。"}],"example":".demo {\n  margin-block: 24px;\n}","notes":["横排时等价于同时设置 margin-top 与 margin-bottom。","块向外边距同样会发生外边距合并，逻辑属性不改变合并规则。"],"syntax":"<'margin-top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-block","browser":{"chrome":"87","firefox":"66","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"margin-block","order":403},{"name":"margin-block-end","js":"marginBlockEnd","zh":"块向结束外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴结束侧的外边距","description":"逻辑属性，作用于块轴结束侧。横排从上到下书写时等价于 margin-bottom，竖排时对应左或右边。支持长度、百分比与负值，百分比以包含块行向尺寸为基准。它参与相邻块级元素的外边距合并，是 margin-block 简写的第二个值，改造多语言组件时与 margin-block-start 成对替换物理属性。","aliases":["块向结束边距","margin-block-end","块尾外边距"],"keywords":["外边距","逻辑属性","书写模式","合并"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，如 16px，可为负。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  margin-block-end: 16px;\n}","notes":["横排书写模式下完全等同 margin-bottom。","与下一个块的外边距会合并，取较大者。"],"syntax":"<'margin-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-block-end","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"margin-block-end","order":404},{"name":"margin-block-start","js":"marginBlockStart","zh":"块向起始外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴起始侧的外边距","description":"逻辑属性，作用于块轴起始侧。横排书写时等价于 margin-top，竖排时对应右或左边。取值与 margin-top 一致，支持长度、百分比与负值。它是 margin-block 简写的第一个值；首个子元素的外边距还可能与父元素合并，导致父容器也被推下，这是排查布局偏移时的常见原因。","aliases":["块向起始边距","margin-block-start","块首外边距"],"keywords":["外边距","逻辑属性","书写模式","合并"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，如 24px，可为负。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  margin-block-start: 0;\n}","notes":["横排书写模式下等同 margin-top。","与父元素之间可能发生外边距合并，可给父级加 overflow 或 padding 阻断。"],"syntax":"<'margin-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-block-start","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"margin-block-start","order":405},{"name":"margin-bottom","js":"marginBottom","zh":"下外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素底部的外边距","description":"设置元素盒子下侧的外边距，取值可为长度、百分比或 auto，支持负值。百分比相对包含块的行向尺寸（宽度）解析而不是高度，这是最容易踩的坑。它与下一个元素的上外边距会合并成较大的一个，因此常出现「设置了却没生效增量」的错觉。对非替换行内元素，垂直外边距不改变行框高度。","aliases":["下外边距","margin-bottom","底部边距"],"keywords":["外边距","盒模型","合并","布局"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，可为负，如 24px、-8px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"auto","d":"自动值，常规块布局中一般计算为 0。"}],"example":".demo {\n  margin-bottom: 24px;\n}","notes":["与相邻元素的上外边距合并，最终间距取两者较大值。","百分比以包含块宽度为基准，而不是高度。"],"syntax":"<length-percentage> | auto | <anchor-size()>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Anchor Positioning","CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-bottom","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"margin-bottom","order":406},{"name":"margin-inline","js":"marginInline","zh":"行向外边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"同时设置行向起始与结束的外边距","description":"margin-inline-start 与 margin-inline-end 的简写，横排 LTR 下对应左右外边距，RTL 下自动翻转。1 个值表示两端相同，2 个值依次为起始、结束。写 margin-inline: auto 配合固定宽度，可让块级元素在行内方向居中；由于方向随书写模式变化，它比 margin: 0 auto 更适合国际化页面。","aliases":["行向外边距","margin-inline","逻辑左右边距"],"keywords":["外边距","逻辑属性","简写","居中"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个长度值，可为负。"},{"v":"<percentage>{1,2}","d":"相对包含块行向尺寸的百分比。"},{"v":"auto","d":"两端自动，配合固定宽度可实现居中。"}],"example":".demo {\n  margin-inline: auto;\n  width: 320px;\n}","notes":["横排 LTR 下等价于 margin-left 与 margin-right。","RTL 页面中起始侧自动变为右边，无需额外覆盖。"],"syntax":"<'margin-top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-inline","browser":{"chrome":"87","firefox":"66","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"margin-inline","order":407},{"name":"margin-inline-end","js":"marginInlineEnd","zh":"行向结束外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴结束侧的外边距","description":"逻辑属性，作用于行轴结束侧。横排 LTR 时等价于 margin-right，RTL 时等价于 margin-left，跟随 direction 自动翻转。支持长度、百分比与负值。它是 margin-inline 简写的第二个值，在列表项、图标与文字间距等需要镜像的场景中，比写死 margin-right 更可靠。","aliases":["行向结束边距","margin-inline-end","行尾外边距"],"keywords":["外边距","逻辑属性","国际化","布局"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，如 8px，可为负。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"},{"v":"auto","d":"自动分配剩余空间。"}],"example":".demo {\n  margin-inline-end: 8px;\n}","notes":["LTR 下等同 margin-right，RTL 下会自动变成左侧。","属于 margin-inline 简写的第二个值。"],"syntax":"<'margin-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-inline-end","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"margin-inline-end","order":408},{"name":"margin-inline-start","js":"marginInlineStart","zh":"行向起始外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴起始侧的外边距","description":"逻辑属性，作用于行轴起始侧。横排 LTR 时等价于 margin-left，RTL 时等价于 margin-right。支持长度、百分比、auto 与负值。缩进、列表符号间距这类需要随语言镜像的留白最适合用它；与 margin-inline-end 组合时，写 margin-inline: auto 可实现居中或均分剩余空间。","aliases":["行向起始边距","margin-inline-start","行首外边距"],"keywords":["外边距","逻辑属性","国际化","缩进"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，如 12px，可为负。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"},{"v":"auto","d":"自动分配剩余空间。"}],"example":".demo {\n  margin-inline-start: 12px;\n}","notes":["LTR 下等同 margin-left。","需要随语言镜像的缩进优先用它而不是 margin-left。"],"syntax":"<'margin-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"取决于布局模型","appliesTo":"与 margin 相同","computed":"长度 / 百分比按指定值，否则 auto","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-inline-start","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"margin-inline-start","order":409},{"name":"margin-left","js":"marginLeft","zh":"左外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素左侧的外边距","description":"设置元素盒子左侧的外边距，支持长度、百分比、auto 与负值。当元素有固定宽度且左右外边距为 auto 时，剩余空间会在两侧均分，从而实现水平居中；负值则可以把元素拉出容器。百分比同样以包含块宽度为基准，与 margin-right 一起决定块级元素的水平位置。","aliases":["左外边距","margin-left","左侧边距"],"keywords":["外边距","盒模型","居中","布局"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，可为负，如 24px、-16px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"auto","d":"自动分配剩余空间，配合 margin-right: auto 可居中。"}],"example":".demo {\n  margin-left: 24px;\n}","notes":["固定宽度加左右 auto 可水平居中。","负值会让元素越过父容器左边界，注意溢出与堆叠。","RTL 场景建议改用 margin-inline-start。"],"syntax":"<length-percentage> | auto | <anchor-size()>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Anchor Positioning","CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-left","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"margin-left","order":410},{"name":"margin-right","js":"marginRight","zh":"右外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素右侧的外边距","description":"设置元素盒子右侧的外边距，支持长度、百分比、auto 与负值，百分比基于包含块宽度。块级元素水平方向不会发生外边距合并，因此它常用来控制元素与右侧内容或滚动条的间距。与 margin-left 都为 auto 且宽度确定时元素水平居中；RTL 布局中应改用逻辑属性 margin-inline-end。","aliases":["右外边距","margin-right","右侧边距"],"keywords":["外边距","盒模型","居中","布局"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，可为负，如 12px、-8px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"auto","d":"自动吸收剩余空间。"}],"example":".demo {\n  margin-right: 12px;\n}","notes":["水平方向外边距不会合并，与 margin-bottom 的规则不同。","多语言镜像场景改用 margin-inline-end 更稳妥。"],"syntax":"<length-percentage> | auto | <anchor-size()>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Anchor Positioning","CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-right","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"margin-right","order":411},{"name":"margin-top","js":"marginTop","zh":"上外边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素顶部的外边距","description":"设置元素盒子上侧的外边距，支持长度、百分比、auto 与负值，百分比以包含块宽度为基准。它最容易出现的坑是与父元素发生外边距合并：子元素设 margin-top 时父容器会一起被推下。此外它与上一个元素的下外边距也会合并。用负值可让元素向上偏移，常用于微调图标与文字的对齐。","aliases":["上外边距","margin-top","顶部边距"],"keywords":["外边距","盒模型","合并","布局"],"values":[{"v":"0","d":"初始值，无外边距。"},{"v":"<length>","d":"长度值，可为负，如 24px、-4px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"auto","d":"自动值，常规块布局中一般计算为 0。"}],"example":".demo {\n  margin-top: -8px;\n}","notes":["与父元素之间可能发生外边距合并，可给父级加 padding 或 overflow 阻断。","弹性或网格项目中不会与父容器合并外边距。"],"syntax":"<length-percentage> | auto | <anchor-size()>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Anchor Positioning","CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/margin-top","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"margin-top","order":412},{"name":"max-block-size","js":"maxBlockSize","zh":"最大块向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"限制元素块向尺寸的上限","description":"逻辑属性，限制元素在块轴方向的尺寸上限。横排书写时等价于 max-height，竖排时等价于 max-width，随 writing-mode 自动切换。初始值 none 表示不限制。常配合 overflow: auto 让长内容在容器内滚动，而内容较少时高度仍由内容决定，是弹窗与侧边栏的常用写法。","aliases":["最大块向尺寸","max-block-size","逻辑最大高度"],"keywords":["尺寸","逻辑属性","上限","滚动"],"values":[{"v":"none","d":"初始值，不限制尺寸。"},{"v":"<length>","d":"固定上限，如 400px。"},{"v":"<percentage>","d":"相对包含块块向尺寸的百分比。"},{"v":"min-content / max-content / fit-content","d":"按内容尺寸决定上限。"}],"example":".demo {\n  max-block-size: 400px;\n  overflow-y: auto;\n}","notes":["横排时等同 max-height。","与 overflow: auto 搭配可实现内容超长时内部滚动。"],"syntax":"<'max-width'>","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块块轴尺寸","appliesTo":"与 width / height 相同","computed":"与 max-width / max-height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/max-block-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"max-block-size","order":439},{"name":"max-height","js":"maxHeight","zh":"最大高度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素高度的最大值","description":"设置元素高度的最大值，初始值 none 表示不限制。当内容高度超过上限时元素高度被截住，此时若配合 overflow: auto 会出现滚动条，否则内容会溢出可见。百分比需要父级高度确定才能解析；它优先于 height 生效，是弹窗、下拉菜单、滚动列表控制最大占位的基础属性。","aliases":["最大高度","max-height","高度上限"],"keywords":["尺寸","上限","滚动","盒模型"],"values":[{"v":"none","d":"初始值，不限制高度。"},{"v":"<length>","d":"固定上限，如 60vh、480px。"},{"v":"<percentage>","d":"相对父元素高度的百分比，需要父级高度确定。"},{"v":"min-content / max-content / fit-content","d":"按内容高度决定上限。"}],"example":".demo {\n  max-height: 60vh;\n  overflow-y: auto;\n}","notes":["内容超出且 overflow 为 visible 时会溢出容器而不是撑高。","与 height 冲突时 max-height 优先。"],"syntax":"none | <length-percentage [0,∞]> | min-content | max-content | fit-content | fit-content(<length-percentage [0,∞]>) | <calc-size()> | <anchor-size()>","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"不适用（生成盒的包含块）","appliesTo":"除不可替换元素与表格列外的元素","computed":"百分比按指定值，长度取绝对值，或 none","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/max-height","browser":{"chrome":"1","firefox":"1","safari":"1.3","edge":"12"},"tier":"core","tags":["可动画"],"id":"max-height","order":440},{"name":"max-inline-size","js":"maxInlineSize","zh":"最大行向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"限制元素行向尺寸的上限","description":"逻辑属性，限制元素在行内轴方向的尺寸上限。横排时等价于 max-width，竖排时等价于 max-height。初始值 none 不限制。用于正文排版时，常写 max-inline-size: 72ch 之类限制行宽以提升可读性，同时让窄屏下元素自然收缩，不需要额外媒体查询。","aliases":["最大行向尺寸","max-inline-size","逻辑最大宽度"],"keywords":["尺寸","逻辑属性","上限","排版"],"values":[{"v":"none","d":"初始值，不限制尺寸。"},{"v":"<length>","d":"固定上限，如 72ch、960px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"},{"v":"min-content / max-content / fit-content","d":"按内容尺寸决定上限。"}],"example":".demo {\n  max-inline-size: 72ch;\n  margin-inline: auto;\n}","notes":["横排时等同 max-width。","限宽加居中常与 margin-inline: auto 一起写，方向自适应。"],"syntax":"<'max-width'>","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块行内轴尺寸","appliesTo":"与 width / height 相同","computed":"与 max-width / max-height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/max-inline-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"max-inline-size","order":441},{"name":"max-width","js":"maxWidth","zh":"最大宽度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素宽度的最大值","description":"设置元素宽度的最大值，初始值 none 表示不限制，百分比相对包含块宽度解析。它常用于响应式布局：容器设 max-width 后在大屏保持固定宽度、小屏自动收缩，配合 margin: auto 实现居中。当 max-width 小于 width 时以 max-width 为准，图片设 max-width: 100% 可避免撑破容器。","aliases":["最大宽度","max-width","宽度上限"],"keywords":["尺寸","上限","响应式","盒模型"],"values":[{"v":"none","d":"初始值，不限制宽度。"},{"v":"<length>","d":"固定上限，如 960px、65ch。"},{"v":"<percentage>","d":"相对包含块宽度的百分比，100% 常用于图片。"},{"v":"min-content / max-content / fit-content","d":"按内容宽度决定上限。"}],"example":".demo {\n  max-width: 100%;\n  height: auto;\n}","notes":["与 width 冲突时 max-width 优先生效。","图片写 max-width: 100% 还需 height: auto 才能保持比例。"],"syntax":"none | <length-percentage [0,∞]> | min-content | max-content | fit-content | fit-content(<length-percentage [0,∞]>) | <calc-size()> | <anchor-size()>","initial":"none","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块宽度","appliesTo":"除表格行与不可替换元素外的元素","computed":"百分比按指定值，长度取绝对值，或 none","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/max-width","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"max-width","order":443},{"name":"min-block-size","js":"minBlockSize","zh":"最小块向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素块向尺寸的下限","description":"逻辑属性，为元素在块轴方向设置最小尺寸。横排时等价于 min-height，竖排时等价于 min-width。初始值 0，但当元素是弹性或网格项目时，auto 值会解析为内容最小尺寸。常用 min-block-size: 100vh 让页面主体至少撑满一屏，或给卡片区设置最小高度避免内容少时高度跳动。","aliases":["最小块向尺寸","min-block-size","逻辑最小高度"],"keywords":["尺寸","逻辑属性","下限","布局"],"values":[{"v":"0","d":"初始值，无最小尺寸限制。"},{"v":"<length>","d":"最小尺寸，如 100vh、240px。"},{"v":"<percentage>","d":"相对包含块块向尺寸的百分比。"},{"v":"auto","d":"弹性/网格项目中解析为内容最小尺寸。"}],"example":".demo {\n  min-block-size: 100vh;\n}","notes":["横排时等同 min-height。","弹性项目中 auto 表示不小于内容尺寸，需要可压缩时显式设 0。"],"syntax":"<'min-width'>","initial":"0","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块块轴尺寸","appliesTo":"与 width / height 相同","computed":"与 min-width / min-height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/min-block-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"min-block-size","order":444},{"name":"min-height","js":"minHeight","zh":"最小高度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素高度的最小值","description":"设置元素高度的最小值，初始值 auto 在普通块布局中一般等于 0，但在弹性与网格项目中会被解析为内容最小尺寸。它保证内容较少时元素仍有足够高度，常见于让容器至少撑满一屏或保持卡片高度一致。与 max-height 冲突时 min-height 优先，百分比则要求父级高度确定。","aliases":["最小高度","min-height","高度下限"],"keywords":["尺寸","下限","布局","盒模型"],"values":[{"v":"auto","d":"初始值，普通块中为 0，弹性/网格项目中取内容最小尺寸。"},{"v":"<length>","d":"固定下限，如 320px、100vh。"},{"v":"<percentage>","d":"相对父元素高度的百分比，需要父级高度确定。"},{"v":"min-content / max-content / fit-content","d":"按内容高度决定下限。"}],"example":".demo {\n  min-height: 320px;\n}","notes":["与 max-height 冲突时 min-height 优先。","纵向弹性容器中项目默认不会小于内容高度，可用 min-height: 0 放开。"],"syntax":"auto | <length-percentage [0,∞]> | min-content | max-content | fit-content | fit-content(<length-percentage [0,∞]>) | <calc-size()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"不适用（生成盒的包含块高度为 0）","appliesTo":"除不可替换元素与表格列外的元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/min-height","browser":{"chrome":"1","firefox":"3","safari":"1.3","edge":"12"},"tier":"core","tags":["可动画"],"id":"min-height","order":445},{"name":"min-inline-size","js":"minInlineSize","zh":"最小行向尺寸","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素行向尺寸的下限","description":"逻辑属性，为元素在行内轴方向设置最小尺寸。横排时等价于 min-width，竖排时等价于 min-height。它最典型的用途是在弹性项目上写 min-inline-size: 0 解除最小内容宽度限制，让长文本或长单词能够收缩，避免出现溢出或把兄弟元素挤出容器。","aliases":["最小行向尺寸","min-inline-size","逻辑最小宽度"],"keywords":["尺寸","逻辑属性","下限","弹性"],"values":[{"v":"0","d":"初始值，无最小尺寸限制。"},{"v":"<length>","d":"最小尺寸，如 200px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"},{"v":"auto","d":"弹性/网格项目中解析为内容最小尺寸。"}],"example":".demo {\n  min-inline-size: 0;\n  flex: 1;\n}","notes":["弹性项目默认 min-inline-size: auto，长内容不收缩，写 0 可解除。","横排时等同 min-width。"],"syntax":"<'min-width'>","initial":"0","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块行内轴尺寸","appliesTo":"与 width / height 相同","computed":"与 min-width / min-height 相同","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/min-inline-size","browser":{"chrome":"57","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"min-inline-size","order":446},{"name":"min-width","js":"minWidth","zh":"最小宽度","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素宽度的最小值","description":"设置元素宽度的最小值，初始值 auto 在普通块中约为 0，在弹性与网格项目中则解析为内容最小宽度。它保证元素不被压得过窄，常用于按钮、表格列与卡片；反过来，弹性布局中文字把容器撑破时，往往需要显式写 min-width: 0 才能让项目正常收缩。","aliases":["最小宽度","min-width","宽度下限"],"keywords":["尺寸","下限","弹性","盒模型"],"values":[{"v":"auto","d":"初始值，弹性/网格项目中取内容最小宽度。"},{"v":"<length>","d":"固定下限，如 200px、12ch。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"},{"v":"min-content / max-content / fit-content","d":"按内容宽度决定下限。"}],"example":".demo {\n  min-width: 0;\n  overflow: hidden;\n}","notes":["弹性项目中默认不会被压缩到小于内容宽度，写 min-width: 0 可解决溢出。","与 max-width 冲突时 min-width 优先。"],"syntax":"auto | <length-percentage [0,∞]> | min-content | max-content | fit-content | fit-content(<length-percentage [0,∞]>) | <calc-size()> | <anchor-size()>","initial":"auto","inherited":"否","animation":"长度 / 百分比 / 颜色插值","percentages":"相对包含块宽度","appliesTo":"除表格行与不可替换元素外的元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Box Sizing"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/min-width","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"min-width","order":447},{"name":"object-fit","js":"objectFit","zh":"替换内容填充","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"控制图片或视频在盒子内的填充方式","description":"决定替换元素（img、video 等）的内容如何适配自身盒子：fill 拉伸可能变形，contain 完整显示并留白，cover 铺满并裁掉多余部分，none 保持原尺寸，scale-down 取 contain 与 none 中较小者。它只改变内容绘制方式，不影响元素布局尺寸，常与 aspect-ratio 或固定宽高搭配使用。","aliases":["图片填充","object-fit","内容适配","图片裁切"],"keywords":["图片","视频","裁切","替换元素"],"values":[{"v":"fill","d":"初始值，拉伸内容填满盒子，比例可能失真。"},{"v":"contain","d":"保持比例完整显示内容，多余区域留白。"},{"v":"cover","d":"保持比例铺满盒子，超出部分被裁剪。"},{"v":"none","d":"保持内容原始尺寸，不缩放，可能超出盒子。"},{"v":"scale-down","d":"在 none 与 contain 中取显示更小的那一个。"}],"example":".demo {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  object-fit: cover;\n}","notes":["只对替换元素（图片、视频等）有效，普通 div 上无效。","配合 aspect-ratio 可稳定占位并避免图片抖动。"],"syntax":"fill | contain | cover | none | scale-down","initial":"fill","inherited":"否","animation":"离散过渡（状态切换）","percentages":"不适用","appliesTo":"可替换元素","computed":"按指定值","specGroups":["CSS Images"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/object-fit","browser":{"chrome":"32","firefox":"36","safari":"10","edge":"79"},"tier":"core","tags":["可动画"],"id":"object-fit","order":449},{"name":"object-position","js":"objectPosition","zh":"替换内容定位","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置图片或视频在盒子内的对齐位置","description":"当替换元素的内容因 object-fit 而没有铺满盒子时，用它决定内容在盒内的对齐位置，语法与 background-position 相同，如 center、left top、20% 80%。初始值 50% 50% 即居中。配合 object-fit: cover 时，它控制裁剪保留哪一部分，常用于让人物头像的关键区域不被裁掉。","aliases":["图片位置","object-position","内容定位","裁切焦点"],"keywords":["图片","定位","裁切","替换元素"],"values":[{"v":"50% 50%","d":"初始值，内容在盒子中居中。"},{"v":"<position>","d":"关键字或百分比组合，如 left top、20% 80%。"},{"v":"left / right / top / bottom / center","d":"单关键字，另一方向默认居中。"},{"v":"<length>","d":"用长度偏移，如 10px 30px。"}],"example":".demo {\n  object-fit: cover;\n  object-position: left top;\n}","notes":["只在内容尺寸与盒子不一致时才有可见效果。","与 object-fit: cover 配合可决定裁剪保留的区域。"],"syntax":"<position>","initial":"50% 50%","inherited":"否","animation":"可重复列表逐项插值","percentages":"相对元素宽度与高度","appliesTo":"可替换元素","computed":"按指定值","specGroups":["CSS Images"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/object-position","browser":{"chrome":"32","firefox":"36","safari":"10","edge":"79"},"tier":"core","tags":["可动画"],"id":"object-position","order":450},{"name":"padding","js":"padding","zh":"内边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"一次性设置四个方向的内边距","description":"padding-top、padding-right、padding-bottom、padding-left 的简写，规则与 margin 相同的顺时针分配：1 个值四边相同，2 个值上下与左右，3 个值为上、左右、下，4 个值为上右下左。它取不到负值，会增加元素实际占位（除非使用 box-sizing: border-box），且背景色会延伸到内边距区域。","aliases":["内边距","padding","内边距简写","补白"],"keywords":["内边距","简写","盒模型","留白"],"values":[{"v":"<length>{1,4}","d":"1 至 4 个非负长度值，按上右下左分配。"},{"v":"<percentage>{1,4}","d":"百分比，四边都相对包含块的行向尺寸解析。"},{"v":"0","d":"无内边距，常用于重置。"}],"example":".demo {\n  padding: 12px 20px;\n}","notes":["内边距不接受负值，要重叠元素请用负的 margin 或 transform。","四边百分比都以包含块宽度为基准，纵向 padding 的百分比同理。"],"syntax":"<'padding-top'>{1,4}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"由各长写属性决定","specGroups":["CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画","简写"],"id":"padding","order":481},{"name":"padding-block","js":"paddingBlock","zh":"块向内边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"同时设置块向起始与结束的内边距","description":"padding-block-start 与 padding-block-end 的简写，横排时对应上下内边距，竖排时对应左右，随书写模式自动切换。1 个值表示两端相同，2 个值依次为起始、结束。它不接受负值，且百分比仍以包含块行向尺寸为基准，因此写 padding-block: 10% 得到的上下内边距是按宽度算出来的。","aliases":["块向内边距","padding-block","逻辑上下内边距"],"keywords":["内边距","逻辑属性","简写","书写模式"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个非负长度值，对应块向两端。"},{"v":"<percentage>{1,2}","d":"百分比相对包含块行向尺寸解析。"},{"v":"0","d":"无内边距。"}],"example":".demo {\n  padding-block: 16px;\n}","notes":["横排时等价于同时设置 padding-top 与 padding-bottom。","百分比以宽度为基准，这一点对纵向内边距同样成立。"],"syntax":"<'padding-top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-block","browser":{"chrome":"87","firefox":"66","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"padding-block","order":482},{"name":"padding-block-end","js":"paddingBlockEnd","zh":"块向结束内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴结束侧的内边距","description":"逻辑属性，作用于块轴结束侧。横排时等价于 padding-bottom，竖排时对应左或右。支持长度与百分比，不接受负值；百分比以包含块行向尺寸为基准。它是 padding-block 简写的第二个值，在卡片底部留白等需要随书写方向变化的场景中替代物理属性。","aliases":["块向结束内边距","padding-block-end","块尾内边距"],"keywords":["内边距","逻辑属性","书写模式","留白"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 8px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  padding-block-end: 8px;\n}","notes":["横排书写模式下等同 padding-bottom。","内边距会增大元素占位，border-box 下则挤压内容区。"],"syntax":"<'padding-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"计算为长度","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-block-end","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"padding-block-end","order":483},{"name":"padding-block-start","js":"paddingBlockStart","zh":"块向起始内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置块轴起始侧的内边距","description":"逻辑属性，作用于块轴起始侧。横排时等价于 padding-top，竖排时对应右或左。支持长度与百分比，不能取负值。它是 padding-block 简写的第一个值，常用于卡头顶部留白；与 padding-top 相比，切换到竖排或 RTL 时无需修改，方向自动跟随书写模式。","aliases":["块向起始内边距","padding-block-start","块首内边距"],"keywords":["内边距","逻辑属性","书写模式","留白"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 20px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  padding-block-start: 8px;\n}","notes":["横排书写模式下等同 padding-top。","内边距不会被外边距合并影响，可用于阻断父子外边距合并。"],"syntax":"<'padding-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"计算为长度","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-block-start","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"padding-block-start","order":484},{"name":"padding-bottom","js":"paddingBottom","zh":"下内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素底部区域的内边距","description":"在元素内容区下方增加留白，使背景与边框范围随之扩大。取值只能为非负长度或百分比，百分比以包含块宽度而非高度为基准。与 margin-bottom 不同，它不会被合并，且会把下一个元素推得更远。对非替换行内元素，纵向内边距不会增加行框高度，但背景会绘制到内边距区域。","aliases":["下内边距","padding-bottom","底部内边距"],"keywords":["内边距","盒模型","留白","布局"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 24px。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"}],"example":".demo {\n  padding-bottom: 24px;\n}","notes":["不能用负值，需要重叠时改用负外边距。","非替换行内元素的纵向内边距不会撑高行框。"],"syntax":"<length-percentage [0,∞]>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-bottom","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"padding-bottom","order":485},{"name":"padding-inline","js":"paddingInline","zh":"行向内边距简写","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"同时设置行向起始与结束的内边距","description":"padding-inline-start 与 padding-inline-end 的简写，横排 LTR 下对应左右内边距，RTL 下自动翻转。1 个值表示两端相同，2 个值依次为起始、结束。它不能取负值，百分比以包含块行向尺寸为基准（也就是最常见的宽度基准），是按钮左右留白在多语言页面中的推荐写法。","aliases":["行向内边距","padding-inline","逻辑左右内边距"],"keywords":["内边距","逻辑属性","简写","按钮"],"values":[{"v":"<length>{1,2}","d":"1 至 2 个非负长度值，对应行向两端。"},{"v":"<percentage>{1,2}","d":"相对包含块行向尺寸的百分比。"},{"v":"0","d":"无内边距。"}],"example":".demo {\n  padding-inline: 20px;\n}","notes":["横排 LTR 下等价于 padding-left 与 padding-right。","按钮、标签这类对称留白用它可自动适配 RTL。"],"syntax":"<'padding-top'>{1,2}","initial":"由各长写属性决定","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"由各长写属性决定","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-inline","browser":{"chrome":"87","firefox":"66","safari":"14.1","edge":"87"},"tier":"core","tags":["可动画","逻辑属性","简写"],"id":"padding-inline","order":486},{"name":"padding-inline-end","js":"paddingInlineEnd","zh":"行向结束内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴结束侧的内边距","description":"逻辑属性，作用于行轴结束侧。横排 LTR 时等价于 padding-right，RTL 时等价于 padding-left，跟随 direction 自动镜像。支持非负长度与百分比。它是 padding-inline 简写的第二个值，适合图标按钮内侧留给点击区域的留白这类需要随语言翻转的场景。","aliases":["行向结束内边距","padding-inline-end","行尾内边距"],"keywords":["内边距","逻辑属性","国际化","留白"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 8px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  padding-inline-end: 8px;\n}","notes":["LTR 下等同 padding-right，RTL 下自动变成左侧。","不接受负值。"],"syntax":"<'padding-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"计算为长度","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-inline-end","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"padding-inline-end","order":487},{"name":"padding-inline-start","js":"paddingInlineStart","zh":"行向起始内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"按书写方向设置行轴起始侧的内边距","description":"逻辑属性，作用于行轴起始侧。横排 LTR 时等价于 padding-left，RTL 时等价于 padding-right。支持非负长度与百分比。它是 padding-inline 简写的第一个值，常用于给列表项或输入框的起始侧留出图标与文字的间距；在 RTL 页面里无需额外覆盖即可自动换边。","aliases":["行向起始内边距","padding-inline-start","行首内边距"],"keywords":["内边距","逻辑属性","国际化","间距"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 12px。"},{"v":"<percentage>","d":"相对包含块行向尺寸的百分比。"}],"example":".demo {\n  padding-inline-start: 12px;\n}","notes":["LTR 下等同 padding-left。","需要随语言镜像的留白优先用它而不是 padding-left。"],"syntax":"<'padding-top'>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块逻辑宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"计算为长度","specGroups":["CSS Logical Properties and Values"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-inline-start","browser":{"chrome":"69","firefox":"41","safari":"12.1","edge":"79"},"tier":"core","tags":["可动画","逻辑属性"],"id":"padding-inline-start","order":488},{"name":"padding-left","js":"paddingLeft","zh":"左内边距","category":"box","categoryName":"盒模型与尺寸","status":"standard","statusLabel":"标准","summary":"设置元素左侧区域的内边距","description":"在元素内容区左侧增加留白，取值只能是非负长度或百分比，百分比基于包含块宽度。它与 padding-right 对称地控制内容与左边框的距离，是最常见的左侧留白手段；与 margin-left 的区别在于内边距属于盒子内部，背景与边框会包住它，且不会与相邻元素合并。","aliases":["左内边距","padding-left","左侧内边距"],"keywords":["内边距","盒模型","留白","布局"],"values":[{"v":"0","d":"初始值，无内边距。"},{"v":"<length>","d":"非负长度值，如 16px、1rem。"},{"v":"<percentage>","d":"相对包含块宽度的百分比。"}],"example":".demo {\n  padding-left: 16px;\n  border-left: 3px solid #4d7cfe;\n}","notes":["内边距在边框以内，背景会覆盖它；外边距在边框以外。","RTL 页面中应改用 padding-inline-start。"],"syntax":"<length-percentage [0,∞]>","initial":"0","inherited":"否","animation":"长度插值","percentages":"相对包含块宽度","appliesTo":"除内部表格显示类型外的所有元素","computed":"百分比按指定值，长度转为绝对值","specGroups":["CSS Box Model"],"mdn":"https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/padding-left","browser":{"chrome":"1","firefox":"1","safari":"1","edge":"12"},"tier":"core","tags":["可动画"],"id":"padding-left","order":489}]);
